public class Main {
    public static void main(String[] args) {
        int i = 42;
        double d = i;           // 自动拓宽: 小范围 -> 大范围
        int back = (int) 3.99;  // 强制收缩: 截断小数,不四舍五入
        System.out.println("拓宽:   int " + i + " -> double " + d);
        System.out.println("收缩:   3.99 -> " + back);

        Integer boxed = Integer.valueOf(100);  // 装箱: 基本类型 -> 包装对象
        int unboxed = boxed;                   // 拆箱: 包装对象 -> 基本类型
        System.out.println("装箱/拆箱: " + boxed + " -> " + unboxed);
        System.out.println("缓存区间 == 比较: " + (Integer.valueOf(127) == Integer.valueOf(127)));
    }
}

