public class Main {
    public static void main(String[] args) {
        int a = 0b1010, b = 0b1100;   // 二进制字面量: 1010 / 1100
        System.out.println("a & b = " + Integer.toBinaryString(a & b));  // 1000
        System.out.println("a | b = " + Integer.toBinaryString(a | b));  // 1110
        System.out.println("a ^ b = " + Integer.toBinaryString(a ^ b));  // 0110
        System.out.println("~a    = " + Integer.toBinaryString(~a));

        System.out.println("1 << 4     = " + (1 << 4));      // 16  相当于 *2^4
        System.out.println("16 >> 2    = " + (16 >> 2));     // 4   相当于 /2^2
        System.out.println("-16 >>> 28 = " + (-16 >>> 28));  // 无符号右移,高位补 0
    }
}

