}

public class Main {
    // 递归: 阶乘
    static long fact(int n) {
        return n <= 1 ? 1 : n * fact(n - 1);
    }

    static void addOne(int x) { x += 1; }      // 基本类型: 只改副本

    static void mutate(int[] a) { a[0] = 2; }  // 数组是引用: 改的是同一对象

    public static void main(String[] args) {
        System.out.println("5! = " + fact(5));
        int n = 10;
        addOne(n);
        System.out.println("值传递后 n = " + n);          // 仍是 10
        int[] arr = {1};
        mutate(arr);
        System.out.println("引用传递后 arr[0] = " + arr[0]); // 变成 2
    }
}

class Student {
    private String name;
    private int score;

    Student(String name, int score) {
        this.name = name;
        setScore(score);          // 统一走校验入口
    }

    public String getName() { return name; }
    public int getScore() { return score; }

    public void setScore(int score) {
        if (score < 0 || score > 100) {
            throw new IllegalArgumentException("分数非法: " + score);
        }
        this.score = score;
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student("张三", 95);
        System.out.println(s.getName() + " -> " + s.getScore());
        try {
            s.setScore(120);
        } catch (IllegalArgumentException e) {
            System.out.println("封装的校验生效: " + e.getMessage());
        }
    }
}

class Animal {
    String name;
    Animal(String name) { this.name = name; }

    String speak() { return name + " 发出声音"; }
}

class Dog extends Animal {
    Dog(String name) { super(name); }

    @Override
    String speak() { return name + " 汪汪叫"; }   // 重写父类行为
}

public class Main {
    public static void main(String[] args) {
        Animal a = new Animal("动物");
        Animal d = new Dog("旺财");
        System.out.println(a.speak());
        System.out.println(d.speak());   // 调用的是 Dog 重写后的方法
    }
}

abstract class Shape {
    abstract double area();     // 抽象方法: 约定"每个形状都会算面积"
}

class Circle extends Shape {
    double r;
    Circle(double r) { this.r = r; }
    @Override double area() { return Math.PI * r * r; }
}

class Rect extends Shape {
    double w, h;
    Rect(double w, double h) { this.w = w; this.h = h; }
    @Override double area() { return w * h; }
}

public class Main {
    public static void main(String[] args) {
        // 父类引用指向子类对象 -> 运行期动态绑定到实际类型的实现
        Shape[] shapes = {new Circle(2), new Rect(3, 4)};
        for (Shape s : shapes) {
            System.out.println(s.getClass().getSimpleName()
                + " 面积 = " + String.format("%.2f", s.area()));
        }
    }
}

interface Flyable {
    void fly();                 // 接口: 只声明能力,不关心怎么实现
}

abstract class Bird implements Flyable {
    String name;
    Bird(String name) { this.name = name; }
    abstract String sing();     // 抽象类: 共享状态 + 抽象行为
}

class Sparrow extends Bird {
    Sparrow(String name) { super(name); }
    @Override String sing() { return name + " 叽叽喳"; }
    @Override public void fly() { System.out.println(name + " 扑棱翅膀飞"); }
}

public class Main {
    public static void main(String[] args) {
        Bird b = new Sparrow("麻雀");
        System.out.println(b.sing());
        b.fly();
        Flyable f = b;          // 同一对象,用接口视角使用
        f.fly();
    }
}

public class Main {
    public static void main(String[] args) {
        // char 是基本类型: 一个 char 保存一个 Unicode 字符
        char c1 = 'A';
        char c2 = '中';
        char c3 = '\u0041';                // 就是 'A'
        System.out.println(c1 + " -> " + (int) c1);   // A -> 65
        System.out.println(c2 + " -> " + (int) c2);   // 中 -> 20013
        System.out.println("c3 == c1: " + (c3 == c1));

        // 码元与码点: emoji 需要两个 char
        String emoji = "😀";
        System.out.println("length: " + emoji.length());                // 2
        System.out.println("codePoints: " + emoji.codePoints().count()); // 1

        // 转义字符
        String q = "ABC\n\u4e2d\u6587";
        System.out.println("q.length: " + q.length()); // 6

        // 字符串连接: 其他类型自动转字符串
        int age = 25;
        System.out.println("age is " + age);
        System.out.println("值是 " + null); // 值是 null

        // 练习: Unicode 编码拼字符串 -> Hi！
        int a = 72, b = 105, c = 65281;
        String s = "" + (char) a + (char) b + (char) c;
        System.out.println(s);
    }
}

public class Main {
    public static void main(String[] args) {
        String a = "abc";
        String b = "abc";
        String c = new String("abc");

        System.out.println(a == b);        // true  (常量池同一个)
        System.out.println(a == c);        // false (堆中新对象)
        System.out.println(a.equals(c));   // true  (内容相同)
        System.out.println(a.hashCode() == c.hashCode()); // true (内容相同 hash 必同)

        // 不可变: 变的是"指向"
        String s = "hello";
        String t = s;
        s = "world";
        System.out.println(t); // hello

        // intern: 把堆中字符串登记进常量池
        String d = new String("abc").intern();
        System.out.println(a == d); // true

        // 隐蔽坑: null 参与拼接不报错
        String n = null;
        System.out.println(n + "x"); // nullx
    }
}

public class Main {
    public static void main(String[] args) {
        // Text Blocks: 多行字符串直接书写,公共缩进自动剥离
        String sql = """
                     SELECT * FROM
                       users
                     WHERE id > 100
                     ORDER BY name DESC
                     """;
        System.out.println(sql);
        System.out.println("末尾带换行: " + sql.endsWith("\n")); // true

        // 行尾 \ 续行: 隐藏换行,拼成一行
        String one = """
                     SELECT * \
                     FROM users
                     """;
        System.out.println(one); // SELECT * FROM users

        // \s 显式保留空格; formatted(...) 动态格式化
        System.out.println("A\sB".length()); // 3
        String json = """
                      {
                        "id": %d,
                        "name": "%s"
                      }
                      """.formatted(1001, "张三");
        System.out.println(json);
    }
}

public class Main {
    public static void main(String[] args) {
        String text = "  Hello, Java 21!  ";

        // Java 11+ 新方法
        System.out.println("isBlank: " + text.isBlank());
        System.out.println("strip: [" + text.strip() + "]");
        System.out.println("-".repeat(20));
        text.strip().lines().forEach(System.out::println);

        // 格式化: 静态方法与 Java 15+ 实例方法
        System.out.println(String.format("姓名:%s, 分数:%.2f", "张三", 95.5));
        System.out.println("姓名:%s, 分数:%.2f".formatted("张三", 95.5));

        // StringBuilder 循环拼接
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= 5; i++) {
            sb.append(i).append(",");
        }
        sb.setLength(sb.length() - 1);
        System.out.println(sb); // 1,2,3,4,5

        // 反转 + split 的坑
        System.out.println(new StringBuilder("madam").reverse()); // madam(回文)
        System.out.println("a.b.c".split("\\.").length);          // 3("."必须转义)
        System.out.println("a,b,,".split(",", -1).length);        // 4(保留末尾空串)
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> scores = List.of(85, 92, 78, 95, 60);
        Map<String, Integer> stats = new LinkedHashMap<>();
        stats.put("最高分", Collections.max(scores));
        stats.put("最低分", Collections.min(scores));
