class InsufficientBalanceException extends RuntimeException {
    InsufficientBalanceException(double need, double have) {
        super("余额不足: 需要 " + need + ", 仅有 " + have);
    }
}

class Account {
    private double balance = 100;

    void withdraw(double amount) {
        if (amount > balance) {
            throw new InsufficientBalanceException(amount, balance);  // throw 抛出
        }
        balance -= amount;
        System.out.println("取款 " + amount + " 成功, 余额 " + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        Account acc = new Account();
        acc.withdraw(30);
        try {
            acc.withdraw(100);
        } catch (InsufficientBalanceException e) {
            System.out.println("业务异常: " + e.getMessage());
        }
    }
}

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws Exception {
        byte[] data = {104, 101, 108, 108, 111};   // "hello"

        try (FileOutputStream out = new FileOutputStream("demo.bin")) {
            out.write(data);                       // 字节流: 按字节写出
        }
        try (FileInputStream in = new FileInputStream("demo.bin")) {
            byte[] buf = in.readAllBytes();        // 字节流: 按字节读回
            System.out.println("读回字节: " + Arrays.toString(buf));
            System.out.println("内容: " + new String(buf));
        }
