}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

public class Main {
    public static void main(String[] args) throws Exception {
        // 缓冲字符流: 按字符读写,带缓冲区更快
        try (BufferedWriter w = new BufferedWriter(new FileWriter("note.txt"))) {
            w.write("第一行: 字符流");
            w.newLine();
            w.write("第二行: 缓冲流减少磁盘交互");
        }
        try (BufferedReader r = new BufferedReader(new FileReader("note.txt"))) {
            r.lines().forEach(System.out::println);
        }

        // 序列化: 对象 -> 字节流, 反序列化: 字节流 -> 对象
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject("可序列化的字符串");
        }
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(bos.toByteArray()))) {
            System.out.println("反序列化: " + ois.readObject());
        }
    }
}

interface Printer<T> {
