}

class Box<T> {                   // 泛型类
    private final T item;
    Box(T item) { this.item = item; }
    T get() { return item; }
}

public class Main {
    static <T> void show(T value) {   // 泛型方法
        System.out.println("泛型方法: " + value + " (" + value.getClass().getSimpleName() + ")");
    }

    public static void main(String[] args) {
        Box<Integer> box = new Box<>(42);
        System.out.println("泛型类: " + box.get());
        show("字符串");
        Printer<String> p = s -> System.out.println("泛型接口: " + s);
        p.print("lambda 实现");
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    static double sum(List<? extends Number> list) {   // 上界: 只读 Number 能力
        double s = 0;
        for (Number n : list) s += n.doubleValue();
        return s;
    }

    static void fillInt(List<? super Integer> list) {  // 下界: 只写 Integer
        list.add(1);
        list.add(2);
    }

    public static void main(String[] args) {
        System.out.println("sum(List<Integer>) = " + sum(Arrays.asList(1, 2, 3)));
        System.out.println("sum(List<Double>)  = " + sum(Arrays.asList(1.5, 2.5)));

        List<Number> dst = new ArrayList<>();
        fillInt(dst);
        System.out.println("下界填充后: " + dst);
        System.out.println("类型擦除: 运行时泛型类是 " + dst.getClass().getName());
    }
}

public class Main {
