        System.out.println("带属性枚举: HIGH.rank = " + Level.HIGH.rank);
    }
}

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Method;

@Retention(RetentionPolicy.RUNTIME)      // 运行期保留,反射才能读到
@Target(ElementType.METHOD)              // 只能标注在方法上
@interface LogPoint {
    String value() default "";
}

public class Main {
    @LogPoint("下单入口")
    void createOrder() { System.out.println("createOrder() 执行"); }

    public static void main(String[] args) throws Exception {
        Main m = new Main();
        for (Method method : Main.class.getDeclaredMethods()) {
            if (method.isAnnotationPresent(LogPoint.class)) {
                LogPoint lp = method.getAnnotation(LogPoint.class);
                System.out.println("发现日志点: " + method.getName() + " -> " + lp.value());
                method.invoke(m);
            }
        }
    }
}

