import java.util.Arrays;
import java.util.List;
import java.util.Optional;

public class Main {
    static void print(String s) { System.out.println("打印: " + s); }

    public static void main(String[] args) {
        List<String> names = Arrays.asList("alice", "bob", "carol");

        names.forEach(Main::print);                          // 静态方法引用
        names.stream().map(String::toUpperCase)              // 实例方法引用
             .forEach(System.out::println);                  // 输出流方法引用

        Optional<String> maybe = Optional.ofNullable(null);
        System.out.println("空值兜底: " + maybe.orElse("默认值"));
        Optional<String> found = names.stream().filter(n -> n.startsWith("b")).findFirst();
        found.ifPresent(n -> System.out.println("找到: " + n));
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    record Student(String name, int score, int classId) {}

    public static void main(String[] args) {
        List<Student> ss = List.of(
            new Student("张三", 85, 1),
            new Student("李四", 92, 1),
            new Student("王五", 78, 2),
            new Student("赵六", 60, 2)
        );

        Map<Integer, Double> avg = ss.stream().collect(
            Collectors.groupingBy(Student::classId, Collectors.averagingDouble(Student::score)));
        System.out.println("班级均分: " + avg);

        String passed = ss.stream().filter(s -> s.score >= 80)
            .sorted(Comparator.comparingInt(Student::score).reversed())
            .map(Student::name).collect(Collectors.joining(", ", "[", "]"));
        System.out.println("及格名单: " + passed);
    }
}

