import java.sql.*;

public class Main {
    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection("jdbc:sqlite::memory:")) {
            Statement st = conn.createStatement();
            st.execute("CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, pwd TEXT)");
            st.execute("INSERT INTO users(name, pwd) VALUES ('admin', '123456'), ('guest', 'guest')");

            String evil = "x' OR '1'='1";   // 注入攻击字符串

            // 危险: 字符串拼接 SQL -> 注入得手, 绕过密码
            ResultSet rs = st.executeQuery(
                "SELECT * FROM users WHERE name='admin' AND pwd='" + evil + "'");
            System.out.println("拼接 SQL 命中行数: " + count(rs) + " (注入得手!)");

            // 安全: PreparedStatement 参数化 -> 数据永远不当语法解析
            PreparedStatement ps = conn.prepareStatement(
                "SELECT * FROM users WHERE name=? AND pwd=?");
            ps.setString(1, "admin");
            ps.setString(2, evil);
            System.out.println("参数化 SQL 命中行数: " + count(ps.executeQuery()) + " (安全)");
        }
    }

    static int count(ResultSet rs) throws SQLException {
        int n = 0;
        while (rs.next()) n++;
        return n;
    }
}

import java.sql.*;

public class Main {
    static final String URL = "jdbc:sqlite:sandbox.db";

    public static void main(String[] args) throws Exception {
        Class.forName("org.sqlite.JDBC");
        try (Connection c = DriverManager.getConnection(URL)) {
            c.setAutoCommit(false);
            try {
                PreparedStatement minus = c.prepareStatement(
                    "UPDATE scores SET score = score - 5 WHERE id = ?");
                PreparedStatement plus = c.prepareStatement(
                    "UPDATE scores SET score = score + 5 WHERE id = ?");

                minus.setInt(1, 1); plus.setInt(1, 2);
                int n1 = minus.executeUpdate();
                int n2 = plus.executeUpdate();
                System.out.println("影响行数: " + n1 + ", " + n2);

                c.commit();
                System.out.println("事务已提交");
            } catch (Exception e) {
                c.rollback();
                System.out.println("异常已回滚: " + e.getMessage());
            }
        }
    }
}

