import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

class Student {
    int id; String name;
    Student(int id, String name) { this.id = id; this.name = name; }
    @Override public String toString() { return "#" + id + " " + name; }
}

interface StudentDao {
    void insert(String name);
    List<Student> findAll();
}

class StudentDaoImpl implements StudentDao {
    private final Connection conn;
    StudentDaoImpl(Connection conn) { this.conn = conn; }

    public void insert(String name) {
        try (PreparedStatement ps = conn.prepareStatement("INSERT INTO students(name) VALUES (?)")) {
            ps.setString(1, name);
            ps.executeUpdate();
        } catch (SQLException e) { throw new RuntimeException(e); }
    }

    public List<Student> findAll() {
        List<Student> list = new ArrayList<>();
        try (Statement st = conn.createStatement();
             ResultSet rs = st.executeQuery("SELECT id, name FROM students ORDER BY id")) {
            while (rs.next()) list.add(new Student(rs.getInt(1), rs.getString(2)));
        } catch (SQLException e) { throw new RuntimeException(e); }
        return list;
    }
}

