            conn.createStatement().execute("CREATE TABLE students(id INTEGER PRIMARY KEY, name TEXT)");
            StudentDao dao = new StudentDaoImpl(conn);
            dao.insert("张三");
            dao.insert("李四");
            System.out.println("DAO 查全部: " + dao.findAll());
        }
    }
}

