import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        String logs = "2026-10-11 08:15:30 INFO  用户 admin 登录成功\n"
                    + "2026-10-11 09:02:11 WARN  磁盘使用率达到 85%\n"
                    + "2026-10-11 12:30:45 ERROR 用户 user 登录失败: 密码错误\n";

        // 分组: (日期) (时间) (级别) (消息)
        Pattern p = Pattern.compile("(\\d{4}-\\d{2}-\\d{2}) (\\d{2}:\\d{2}:\\d{2}) (\\w+)\\s+(.*)");
        Matcher m = p.matcher(logs);

        int count = 0;
        while (m.find()) {
            count++;
            System.out.printf("[%s] %s %s | %s%n",
                    m.group(3), m.group(1), m.group(2), m.group(4));
        }
        System.out.println("共解析 " + count + " 条日志");

        // 命名分组版本(推荐,可读性好)
        Pattern p2 = Pattern.compile("(?<level>INFO|WARN|ERROR)\\s+(?<msg>.*)");
        Matcher m2 = p2.matcher(logs);
        System.out.println("--- 只看 ERROR ---");
        while (m2.find()) {
            if ("ERROR".equals(m2.group("level"))) {
                System.out.println("发现错误: " + m2.group("msg"));
            }
        }

        // 贪婪 vs 非贪婪对比
        String html = "<p>第一段</p><p>第二段</p>";
        Matcher g1 = Pattern.compile("<p>.*</p>").matcher(html);
        Matcher g2 = Pattern.compile("<p>.*?</p>").matcher(html);
        if (g1.find()) System.out.println("贪婪匹配:   " + g1.group());
        while (g2.find()) System.out.println("非贪婪匹配: " + g2.group());
    }
}

public class Main {
    public static void main(String[] args) {
        // 1. 手机号脱敏: 保留前 3 后 4,中间 ****
        String phone = "13812345678";
        String masked = phone.replaceAll("(\\d{3})\\d{4}(\\d{4})", "$1****$2");
        System.out.println("手机号脱敏: " + masked);

        // 2. 姓名脱敏: 保留姓氏,其余变 *
        String name = "欧阳娜娜";
        String maskedName = name.replaceAll("^(.)(.*)$", "$1" + "*".repeat(name.length() - 1));
        System.out.println("姓名脱敏: " + maskedName);

        // 3. 日志中的敏感词替换
        String log = "用户密码是 abc123,千万别泄露密码";
        System.out.println("脱敏日志: " + log.replaceAll("密码\\S{0,10}", "[已脱敏]"));

        // 4. 脏 CSV 切分: 分隔符混用中英文逗号、分号,空格不固定
        String dirty = "张三, 李四，王五 ;  赵六,孙七";
        String[] names = dirty.split("[,，;]\\s*");
        System.out.println("切分出 " + names.length + " 个人: " + String.join(" | ", names));

        // 5. 连续空白压缩成一个空格
        String messy = "hello    world   \t  java";
        System.out.println("压缩空白: [" + messy.replaceAll("\\s+", " ") + "]");

        // 6. 易错示范: split(".") 按任意字符切,结果为空!
        System.out.println("错误切分长度: " + "a.b.c".split(".").length);       // 0
        System.out.println("正确切分长度: " + "a.b.c".split("\\.").length);    // 3
    }
}

import java.util.regex.Pattern;

public class Main {

    /** 表单校验工具类: Pattern 预编译 + 静态方法 */
    static class Validators {
        private Validators() {} // 禁止实例化

        private static final Pattern PHONE = Pattern.compile("1[3-9]\\d{9}");
        private static final Pattern EMAIL = Pattern.compile("\\w+@[a-zA-Z0-9]+(\\.[a-zA-Z]{2,})+");
        private static final Pattern ID_CARD = Pattern.compile("\\d{17}[\\dXx]");
        private static final Pattern NUMBER = Pattern.compile("-?\\d+(\\.\\d+)?");

        public static boolean isPhone(String s)   { return s != null && PHONE.matcher(s).matches(); }
        public static boolean isEmail(String s)   { return s != null && EMAIL.matcher(s).matches(); }
        public static boolean isIdCard(String s)  { return s != null && ID_CARD.matcher(s).matches(); }
        public static boolean isNumber(String s)  { return s != null && NUMBER.matcher(s).matches(); }

        /** 强密码: 至少 8 位,含大写、小写、数字 */
        public static boolean isStrongPassword(String s) {
            return s != null && s.length() >= 8
                    && s.matches(".*[A-Z].*")
                    && s.matches(".*[a-z].*")
                    && s.matches(".*\\d.*");
        }
    }

    public static void main(String[] args) {
        // 模拟一次注册表单校验
        String[][] form = {
            {"手机号",   "13812345678",      String.valueOf(Validators.isPhone("13812345678"))},
            {"手机号错", "123456",           String.valueOf(Validators.isPhone("123456"))},
            {"邮箱",     "dev@workbuddy.cn", String.valueOf(Validators.isEmail("dev@workbuddy.cn"))},
            {"邮箱错",   "dev@",             String.valueOf(Validators.isEmail("dev@"))},
            {"密码",     "Java2026ok",       String.valueOf(Validators.isStrongPassword("Java2026ok"))},
            {"密码弱",   "12345678",         String.valueOf(Validators.isStrongPassword("12345678"))},
        };
        for (String[] row : form) {
            System.out.printf("%-8s %-18s -> %s%n", row[0], row[1], row[2]);
        }
    }
}

public class Main {

    /** 30 行迷你测试框架: JUnit 的思想内核 */
    static class MiniTest {
        static int passed = 0, failed = 0;

        static void assertEquals(Object expected, Object actual, String caseName) {
            if (expected.equals(actual)) {
                passed++;
                System.out.println("  PASS " + caseName);
            } else {
                failed++;
                System.out.println("  FAIL " + caseName
                        + " | 期望: " + expected + ", 实际: " + actual);
            }
        }

        static void assertTrue(boolean condition, String caseName) {
            assertEquals(true, condition, caseName);
        }

        static void report() {
            System.out.printf("%n结果: %d 通过, %d 失败%n", passed, failed);
        }
    }

    /** 被测对象: 计分器 */
    static class ScoreCalculator {
        /** 满分 100,平时分占 40%,考试占 60% */
        int total(int usual, int exam) {
            return (int) (usual * 0.4 + exam * 0.6);
        }
        boolean isPass(int totalScore) {
            return totalScore >= 60;
        }
    }

    public static void main(String[] args) {
        ScoreCalculator calc = new ScoreCalculator();

        System.out.println("--- 总分计算 ---");
        MiniTest.assertEquals(100, calc.total(100, 100), "双满分应为 100");
        // 下面这条预期故意写成 76(正确是 86),观察 FAIL 输出
        MiniTest.assertEquals(76, calc.total(80, 90), "80*0.4 + 90*0.6 = ?");
        MiniTest.assertEquals(0, calc.total(0, 0), "双零分应为 0");

        System.out.println("--- 及格判定(边界!) ---");
        MiniTest.assertTrue(calc.isPass(60), "60 分应及格(边界值)");
        MiniTest.assertTrue(!calc.isPass(59), "59 分不应及格(边界值-1)");

        MiniTest.report();
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {

    /** 被测类: 购物车 */
    static class Cart {
        private final List<Integer> prices = new ArrayList<>();
        void add(int price) {
            if (price < 0) throw new IllegalArgumentException("价格不能为负");
            prices.add(price);
        }
        int total() { return prices.stream().mapToInt(Integer::intValue).sum(); }
        int count() { return prices.size(); }
    }

    // ---- 以下模拟 JUnit 的组织方式(真实项目用 @Test + mvn test 运行) ----

    static Cart cart; // Fixture: 每个"测试"前重建,保证用例独立

    static void beforeEach() { cart = new Cart(); }

    static void testAddAndTotal() {
        beforeEach();
        cart.add(100); cart.add(200);
        check(cart.total() == 300 && cart.count() == 2, "加两件商品后总额 300、数量 2");
    }

    static void testEmptyCart() {
        beforeEach();
        check(cart.total() == 0, "空购物车总额为 0");
    }

    static void testNegativePriceThrows() {
        beforeEach();
        boolean thrown = false;
        try {
            cart.add(-1);
        } catch (IllegalArgumentException e) {
            thrown = true; // 真实 JUnit 写法: assertThrows(IllegalArgumentException.class, () -> cart.add(-1))
        }
        check(thrown, "加负数价格应抛 IllegalArgumentException");
    }

    static int pass = 0, fail = 0;
    static void check(boolean cond, String name) {
        if (cond) { pass++; System.out.println("  PASS " + name); }
        else      { fail++; System.out.println("  FAIL " + name); }
    }

    public static void main(String[] args) {
        testAddAndTotal();
        testEmptyCart();
        testNegativePriceThrows();
        System.out.printf("%n%d 通过, %d 失败%n", pass, fail);
        System.out.println("提示: 在本地 spring-boot-learning 模块执行 mvn test 可看真实 JUnit 效果");
    }
}

public class Main {

    /** 被测方法: 分数 -> 等级(含防御性校验) */
    static String grade(int score) {
        if (score < 0 || score > 100) throw new IllegalArgumentException("分数必须在 0-100");
        if (score >= 90) return "A";
        if (score >= 80) return "B";
        if (score >= 60) return "C";
        return "D";
    }

    public static void main(String[] args) {
        // 参数化思维: 用例 = 数据表(输入, 期望)
        Object[][] cases = {
            // 等价类: 每个等级区间取代表
            {95, "A"}, {85, "B"}, {70, "C"}, {30, "D"},
            // 边界值: 分界线两侧(最易出错!)
            {90, "A"}, {89, "B"}, {80, "B"}, {79, "C"},
            {60, "C"}, {59, "D"}, {100, "A"}, {0, "D"},
        };

        int pass = 0, fail = 0;
        for (Object[] c : cases) {
            String actual = grade((int) c[0]);
            boolean ok = actual.equals(c[1]);
            if (ok) pass++; else fail++;
            System.out.printf("%s score=%-3d 期望=%s 实际=%s%n",
                    ok ? "PASS" : "FAIL", c[0], c[1], actual);
        }

        // 异常路径: 非法输入必须抛异常
        for (int bad : new int[]{-1, 101, Integer.MAX_VALUE}) {
            try {
                grade(bad);
                fail++;
                System.out.println("FAIL score=" + bad + " 应抛异常但没抛");
            } catch (IllegalArgumentException e) {
                pass++;
                System.out.println("PASS score=" + bad + " 正确抛出: " + e.getMessage());
            }
        }

        System.out.printf("%n总计 %d 用例: %d 通过, %d 失败%n", pass + fail, pass, fail);
    }
}

public class Main {
