public class Main {
    public static void main(String[] args) throws InterruptedException {
        // 打印线程状态变化
        Thread t = new Thread(() -> {
            try { Thread.sleep(300); } catch (InterruptedException e) { }
        });
        System.out.println("new 之后:    " + t.getState());      // NEW
        t.start();
        System.out.println("start 之后:  " + t.getState());      // RUNNABLE
        Thread.sleep(50);
        System.out.println("睡眠中:      " + t.getState());      // TIMED_WAITING
        t.join(); // 等 t 结束
        System.out.println("join 之后:   " + t.getState());      // TERMINATED

        System.out.println("--- join 实战: 等两个下载任务完成再汇总 ---");
        long begin = System.currentTimeMillis();
        Thread d1 = new Thread(() -> download("文件A", 400));
        Thread d2 = new Thread(() -> download("文件B", 600));
        d1.start(); d2.start();
        d1.join();  d2.join(); // 删掉这两行,汇总会抢跑!
        System.out.println("全部下载完成,总耗时: " + (System.currentTimeMillis() - begin) + "ms");
    }

    static void download(String name, int ms) {
        try {
            Thread.sleep(ms);
            System.out.println(name + " 下载完成 (" + ms + "ms, 线程: "
                    + Thread.currentThread().getName() + ")");
        } catch (InterruptedException e) {
