        }
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Thread worker = new Thread(() -> {
            long count = 0;
            // 标准模板: 循环条件检查中断标志
            while (!Thread.currentThread().isInterrupted()) {
                count++;
                if (count % 5 == 0) {
                    System.out.println("工作中... 已处理 " + count + " 个任务");
                }
                try {
                    Thread.sleep(200); // 睡眠中被 interrupt 会抛异常
                } catch (InterruptedException e) {
                    System.out.println("收到中断信号(睡眠中被唤醒),准备收尾...");
                    break; // 协作式退出: 在安全位置结束循环
                }
            }
            System.out.println("线程优雅退出,共处理 " + count + " 个任务");
        }, "计数工");

        worker.start();
        Thread.sleep(1000);          // 让它干 1 秒活
        System.out.println("主线程: 1 秒到,发送停止信号");
        worker.interrupt();          // 发信号,而不是 stop()
        worker.join();               // 等它收尾完
        System.out.println("主线程: 确认 worker 已安全停止,程序结束");
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Thread heartbeat = new Thread(() -> {
            int i = 0;
            while (true) { // 永不主动停止!
                System.out.println("心跳 " + (++i) + " (守护线程在后台运行)");
                try {
                    Thread.sleep(300);
                } catch (InterruptedException e) {
                    break;
                }
            }
        }, "心跳线程");

        heartbeat.setDaemon(true); // 关键: 设为守护线程(必须在 start 前)
        heartbeat.start();
        System.out.println("心跳线程是守护线程? " + heartbeat.isDaemon());

        // 主线程(用户线程)干 1 秒活就结束
        Thread.sleep(1000);
        System.out.println("主线程结束 -> JVM 退出,守护线程被自动回收,finally 都不执行");

        // 试试: 注释掉 setDaemon(true) 那行再运行,
        // 心跳线程永不停止 -> 沙箱 5 秒超时强制结束(这就是用户线程阻止 JVM 退出的现象)
    }
}

public class Main {
    static int count = 0; // 共享可变状态: 万恶之源

    public static void main(String[] args) throws InterruptedException {
        for (int round = 1; round <= 3; round++) {
            count = 0;
            Thread t1 = new Thread(Main::increment);
            Thread t2 = new Thread(Main::increment);
            t1.start(); t2.start();
            t1.join();  t2.join();
            System.out.printf("第 %d 轮: 期望 20000, 实际 %d, 丢失 %d 次自增%n",
                    round, count, 20000 - count);
        }
        System.out.println("--- i++ 的三步分解 ---");
        System.out.println("读取 count -> 计算 count+1 -> 写回 count");
        System.out.println("两个线程可能同时读到同一个值,各算各的,其中一个写回被覆盖");
    }

    static void increment() {
        for (int i = 0; i < 10000; i++) {
            count++; // 非原子操作: 读-改-写三步
        }
    }
}

public class Main {
    static int count = 0;
    // 专用锁对象: 比 synchronized(this) 更可控
    static final Object LOCK = new Object();

    public static void main(String[] args) throws InterruptedException {
        // --- 修复版: synchronized 保护 count++ ---
        for (int round = 1; round <= 3; round++) {
            count = 0;
            Thread t1 = new Thread(Main::safeIncrement);
            Thread t2 = new Thread(Main::safeIncrement);
            t1.start(); t2.start();
            t1.join();  t2.join();
            System.out.printf("[加锁] 第 %d 轮: %d (期望 20000)%n", round, count);
        }

        // --- 反例: 各用各的锁,等于没锁 ---
        count = 0;
        Object lockA = new Object(), lockB = new Object();
        Thread x = new Thread(() -> incrementWith(lockA));
        Thread y = new Thread(() -> incrementWith(lockB)); // 不同锁!
        x.start(); y.start();
        x.join();  y.join();
        System.out.println("[不同锁] 结果: " + count + " (锁对象不同,互斥失效)");
    }

    static void safeIncrement() {
        for (int i = 0; i < 10000; i++) {
            synchronized (LOCK) { // 同一把锁 -> 互斥,结果必然正确
                count++;
            }
        }
    }

    static void incrementWith(Object lock) {
        for (int i = 0; i < 10000; i++) {
            synchronized (lock) {
                count++;
            }
        }
    }
}

public class Main {

    static class Account {
        final int id;
        String name;
        int balance;
        Account(int id, String name, int balance) {
            this.id = id; this.name = name; this.balance = balance;
        }
    }

    /** 错误示范: 按 转出->转入 顺序加锁,双向转账时死锁 */
    static void transferDeadlock(Account from, Account to, int amount) {
        synchronized (from) {
            sleep(10); // 放大死锁窗口
            synchronized (to) {
                from.balance -= amount;
                to.balance += amount;
            }
        }
    }

    /** 修复版: 永远先锁 id 小的账户,破坏循环等待 */
    static void transferSafe(Account from, Account to, int amount) {
        Account first  = from.id < to.id ? from : to;
        Account second = from.id < to.id ? to : from;
        synchronized (first) {
            sleep(10);
            synchronized (second) {
                from.balance -= amount;
                to.balance += amount;
            }
        }
    }

    static void sleep(int ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }

    public static void main(String[] args) throws InterruptedException {
        Account alice = new Account(1, "Alice", 1000);
        Account bob   = new Account(2, "Bob",   1000);

        System.out.println("--- 死锁复现(2 秒后由超时检测) ---");
        Thread t1 = new Thread(() -> transferDeadlock(alice, bob, 100), "甲->乙");
        Thread t2 = new Thread(() -> transferDeadlock(bob, alice, 200), "乙->甲");
        t1.start(); t2.start();
        t1.join(2000); t2.join(2000); // 最多等 2 秒
        if (t1.isAlive() || t2.isAlive()) {
            System.out.println("死锁发生! 两个线程互相等待,永远僵持");
            System.out.println("t1 状态: " + t1.getState() + ", t2 状态: " + t2.getState());
        }

        System.out.println("--- 修复版: 固定加锁顺序 ---");
        Account a = new Account(1, "Alice", 1000);
        Account b = new Account(2, "Bob",   1000);
        Thread s1 = new Thread(() -> transferSafe(a, b, 100));
        Thread s2 = new Thread(() -> transferSafe(b, a, 200));
        s1.start(); s2.start();
        s1.join();  s2.join();
        System.out.println("转账完成: Alice=" + a.balance + ", Bob=" + b.balance
                + " (总额 " + (a.balance + b.balance) + " 不变)");
    }
}

import java.util.LinkedList;
import java.util.Queue;

public class Main {

    /** 手写阻塞队列(教学版,生产请用 ArrayBlockingQueue) */
    static class MiniBlockingQueue {
        private final Queue<String> queue = new LinkedList<>();
        private final int capacity = 3;

        public synchronized void put(String item) throws InterruptedException {
            while (queue.size() == capacity) { // 必须用 while!
                System.out.println("  [队列满] " + Thread.currentThread().getName() + " 等待...");
                wait();
            }
            queue.offer(item);
            System.out.println("  生产: " + item + " (库存 " + queue.size() + ")");
            notifyAll(); // 叫醒可能在等的消费者
        }

        public synchronized String take() throws InterruptedException {
            while (queue.isEmpty()) { // 必须用 while!
                System.out.println("  [队列空] 消费者等待...");
                wait();
            }
            String item = queue.poll();
            System.out.println("  消费: " + item + " (库存 " + queue.size() + ")");
            notifyAll(); // 叫醒可能在等的生产者
            return item;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        MiniBlockingQueue q = new MiniBlockingQueue();

        // 2 个生产者,各生产 4 个面包
        Runnable producer = () -> {
            try {
                for (int i = 1; i <= 4; i++) {
                    q.put(Thread.currentThread().getName() + "-面包" + i);
                    Thread.sleep(150);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };
        // 1 个消费者,吃 8 个
        Thread consumer = new Thread(() -> {
            try {
                for (int i = 0; i < 8; i++) {
                    q.take();
                    Thread.sleep(400); // 吃得慢,队列会满
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "吃货");

        Thread p1 = new Thread(producer, "面包师甲");
        Thread p2 = new Thread(producer, "面包师乙");
        p1.start(); p2.start(); consumer.start();
        p1.join();  p2.join();  consumer.join();
        System.out.println("全部生产消费完毕!");
    }
}

import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static final ReentrantLock lockA = new ReentrantLock();
    static final ReentrantLock lockB = new ReentrantLock();

    public static void main(String[] args) throws InterruptedException {
        // 线程1: 先 A 后 B;线程2: 先 B 后 A —— synchronized 写法必死锁
        // 用 tryLock 限时: 拿不到就松手重来,破坏"持有并等待"
        Thread t1 = new Thread(() -> work("线程1", lockA, lockB));
        Thread t2 = new Thread(() -> work("线程2", lockB, lockA));
        t1.start(); t2.start();
        t1.join();  t2.join();
        System.out.println("两个线程都完成了,没有死锁!");
    }

    static void work(String name, ReentrantLock first, ReentrantLock second) {
        int retries = 0;
        while (retries < 5) {
            boolean gotFirst = false, gotSecond = false;
            try {
                gotFirst = first.tryLock(200, TimeUnit.MILLISECONDS); // 限时抢第一把锁
                if (!gotFirst) { retries++; continue; }
                gotSecond = second.tryLock(200, TimeUnit.MILLISECONDS); // 限时抢第二把锁
                if (!gotSecond) {
                    retries++;
                    continue; // finally 会放掉第一把锁,下一轮重来
                }
                // 两把锁都拿到,干活
                System.out.println(name + " 拿到两把锁,开始工作(第 " + (retries + 1) + " 次尝试)");
                Thread.sleep(100);
                System.out.println(name + " 工作完成");
                return;
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            } finally {
                if (gotSecond) second.unlock(); // 铁律: finally 中释放
                if (gotFirst)  first.unlock();
            }
        }
        System.out.println(name + " 重试多次后放弃,避免无限僵持");
    }
}

import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        // --- ConcurrentHashMap.merge: 多线程词频统计 ---
        List<String> words = List.of(
                "java", "python", "java", "go", "java", "python", "rust", "go", "java");
        ConcurrentHashMap<String, Integer> freq = new ConcurrentHashMap<>();

        // 4 个线程并发统计同一批词
        Thread[] ts = new Thread[4];
        for (int i = 0; i < 4; i++) {
            ts[i] = new Thread(() -> {
                for (int round = 0; round < 1000; round++) {
                    for (String w : words) {
                        freq.merge(w, 1, Integer::sum); // 原子: 不存在放1,存在则累加
                    }
                }
            });
            ts[i].start();
        }
        for (Thread t : ts) t.join();

        System.out.println("词频统计(4 线程 x 1000 轮):");
        freq.forEach((k, v) -> System.out.println("  " + k + " = " + v));
        System.out.println("java 期望 = " + (4 * 1000 * 4) + " (每轮出现4次)");

        // --- computeIfAbsent: 缓存模式 ---
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        String value = cache.computeIfAbsent("user:1001", k -> {
            System.out.println("缓存未命中,查询数据库: " + k);
            return "{name: 张三}";
        });
        System.out.println("第一次: " + value);
        System.out.println("第二次: " + cache.computeIfAbsent("user:1001", k -> "不会执行"));

        // --- CopyOnWriteArrayList: 遍历中修改不报错 ---
        CopyOnWriteArrayList<String> listeners = new CopyOnWriteArrayList<>(
                List.of("日志监听", "监控监听", "报警监听"));
        for (String l : listeners) {
            if (l.contains("监控")) {
                listeners.remove(l); // 遍历中删除也安全(普通 ArrayList 会抛异常)
                System.out.println("遍历中移除了: " + l);
            }
        }
        System.out.println("剩余监听器: " + listeners);
    }
}

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.LongAdder;

public class Main {
    static long syncCount = 0;
    static final Object LOCK = new Object();
    static final AtomicLong atomicCount = new AtomicLong();
    static final LongAdder adderCount = new LongAdder();

    public static void main(String[] args) throws InterruptedException {
        int threads = 4, perThread = 25000;
        long expect = (long) threads * perThread;

        // 1. synchronized 版
        runAndWait(threads, () -> {
            for (int i = 0; i < perThread; i++) {
                synchronized (LOCK) { syncCount++; }
            }
        });
        System.out.println("synchronized: " + syncCount + " (期望 " + expect + ")");

        // 2. AtomicLong 版(CAS 无锁)
        runAndWait(threads, () -> {
            for (int i = 0; i < perThread; i++) {
                atomicCount.incrementAndGet(); // 一行,无需锁
            }
        });
        System.out.println("AtomicLong:   " + atomicCount.get() + " (期望 " + expect + ")");

        // 3. LongAdder 版(高并发计数专用)
        runAndWait(threads, () -> {
            for (int i = 0; i < perThread; i++) {
                adderCount.increment();
            }
        });
        System.out.println("LongAdder:    " + adderCount.sum() + " (期望 " + expect + ")");

        // CAS 演示: compareAndSet 的"期望不符则失败"
        AtomicLong demo = new AtomicLong(10);
        System.out.println("CAS(10->20) 成功? " + demo.compareAndSet(10, 20)); // true
        System.out.println("CAS(10->99) 成功? " + demo.compareAndSet(10, 99)); // false,已是20
        System.out.println("当前值: " + demo.get());
    }

    static void runAndWait(int n, Runnable task) throws InterruptedException {
        Thread[] ts = new Thread[n];
        for (int i = 0; i < n; i++) { ts[i] = new Thread(task); ts[i].start(); }
        for (Thread t : ts) t.join();
    }
}

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class Main {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(3);

        // 模拟两个远程查询(各耗时 300ms/500ms)
        CompletableFuture<String> userFuture = CompletableFuture.supplyAsync(() -> {
            sleep(300);
            System.out.println("  [完成] 查询用户信息 (" + Thread.currentThread().getName() + ")");
            return "张三(VIP3)";
        }, pool);

        CompletableFuture<String> orderFuture = CompletableFuture.supplyAsync(() -> {
            sleep(500);
            System.out.println("  [完成] 查询最近订单 (" + Thread.currentThread().getName() + ")");
            return "订单#9527 已发货";
        }, pool);

        long begin = System.currentTimeMillis();

        // 合并两个异步结果: 并行执行,都完成后才合并
        CompletableFuture<String> page = userFuture.thenCombine(orderFuture,
                (user, order) -> "个人主页 | " + user + " | " + order);

        System.out.println("主线程不阻塞,可以先做别的事...");

        // 链式加工 + 异常兜底
        String result = page
                .thenApply(s -> s + " | 更新时间: 刚刚")
                .exceptionally(ex -> "页面加载失败,展示默认页")
                .get(); // 最终汇总时才等待

        System.out.println(result);
        System.out.println("总耗时: " + (System.currentTimeMillis() - begin) + "ms"
                + " (并行! 串行需要 300+500=800ms)");

        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
    }

    static void sleep(int ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        int total = 10_000;
        AtomicInteger done = new AtomicInteger();
        CountDownLatch latch = new CountDownLatch(total);

        long begin = System.currentTimeMillis();

        // 方式一: 每任务一个虚拟线程的 Executor(推荐写法)
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < total; i++) {
                executor.submit(() -> {
                    try {
                        Thread.sleep(50); // 模拟一点 IO 等待
                        done.incrementAndGet();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    } finally {
                        latch.countDown();
                    }
                });
            }
            latch.await();
        } // try-with-resources 自动等待所有任务完成

        long cost = System.currentTimeMillis() - begin;
        System.out.println("完成 " + done.get() + " 个虚拟线程任务,总耗时 " + cost + "ms");
        System.out.println("如果换成平台线程池(200 线程): 10000 个任务 x 50ms / 200 ≈ 2500ms");

        // 方式二: 直接创建单个虚拟线程
        Thread vt = Thread.ofVirtual().name("我的虚拟线程").start(() ->
                System.out.println("我是守护线程吗? " + Thread.currentThread().isDaemon()
                        + " | 是虚拟线程吗? " + Thread.currentThread().isVirtual()));
        vt.join();
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {

    static final AtomicInteger counter = new AtomicInteger();

    /** 模拟 IO 型任务: 大部分时间在等(数据库/网络) */
    static void ioTask() {
        try {
            Thread.sleep(20); // 模拟等待 IO
            counter.incrementAndGet();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static long benchmark(String name, ExecutorService pool, int tasks) throws InterruptedException {
        counter.set(0);
        long begin = System.currentTimeMillis();
        for (int i = 0; i < tasks; i++) {
            pool.submit(Main::ioTask);
        }
        pool.shutdown();
        while (!pool.isTerminated()) {
            Thread.sleep(10);
        }
        long cost = System.currentTimeMillis() - begin;
        System.out.printf("%-28s %d 个任务完成, 耗时 %dms%n", name, counter.get(), cost);
        return cost;
    }

    public static void main(String[] args) throws InterruptedException {
        int tasks = 500;

        // 平台线程池: 50 个线程,500 任务 x 20ms / 50 ≈ 200ms 理论下限
        long platform = benchmark("平台线程池(50线程)",
                Executors.newFixedThreadPool(50), tasks);

        // 虚拟线程: 每任务一个,几乎全部并行
        long virtual = benchmark("虚拟线程(每任务一个)",
                Executors.newVirtualThreadPerTaskExecutor(), tasks);

        System.out.printf("%n虚拟线程加速比: %.1fx%n", (double) platform / virtual);
        System.out.println("结论: IO 越重、并发越高,虚拟线程优势越明显;CPU 密集任务无此效果");
    }
}

