import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        try {
            // 1. 启动回声服务器(独立线程)
            Thread server = new Thread(Main::echoServer, "回声服务器");
            server.start();
            Thread.sleep(200); // 等服务器就绪

            // 2. 客户端连接并发送三条消息
            try (Socket socket = new Socket("127.0.0.1", 18888);
                 BufferedWriter out = new BufferedWriter(new OutputStreamWriter(
                         socket.getOutputStream(), StandardCharsets.UTF_8));
                 BufferedReader in = new BufferedReader(new InputStreamReader(
                         socket.getInputStream(), StandardCharsets.UTF_8))) {

                String[] messages = {"hello", "java 网络编程", "bye"};
                for (String msg : messages) {
                    out.write(msg + "\n");
                    out.flush();
                    String echo = in.readLine();
                    System.out.println("客户端发送: " + msg + " -> 收到回声: " + echo);
                    if ("bye".equals(msg)) break;
                }
            }
            server.join(2000);
            System.out.println("通信结束");
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制端口绑定: " + e.getMessage());
            System.out.println("请把代码复制到本地运行,效果相同");
        }
    }

    static void echoServer() {
        try (ServerSocket ss = new ServerSocket(18888)) {
            System.out.println("服务器启动,监听 18888...");
            try (Socket client = ss.accept(); // 阻塞等待客户端
                 BufferedReader in = new BufferedReader(new InputStreamReader(
                         client.getInputStream(), StandardCharsets.UTF_8));
                 BufferedWriter out = new BufferedWriter(new OutputStreamWriter(
                         client.getOutputStream(), StandardCharsets.UTF_8))) {
                System.out.println("客户端已连接: " + client.getInetAddress());
                String line;
                while ((line = in.readLine()) != null) {
                    System.out.println("服务器收到: " + line);
                    out.write("ECHO: " + line + "\n");
                    out.flush();
                    if ("bye".equals(line)) break;
                }
            }
        } catch (IOException e) {
            System.out.println("服务器异常: " + e.getMessage());
        }
    }
}

import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        try {
            // UDP 接收端(无需 accept,直接 receive)
            Thread receiver = new Thread(() -> {
                try (DatagramSocket socket = new DatagramSocket(19999)) {
                    System.out.println("UDP 接收端就绪,端口 19999");
                    byte[] buf = new byte[1024];
                    DatagramPacket packet = new DatagramPacket(buf, buf.length);
                    socket.receive(packet); // 阻塞等包裹
                    String msg = new String(packet.getData(), 0, packet.getLength(),
                            StandardCharsets.UTF_8);
                    System.out.println("收到来自 " + packet.getAddress() + " 的包裹: " + msg);
                } catch (Exception e) {
                    System.out.println("接收端异常: " + e.getMessage());
                }
            });
            receiver.start();
            Thread.sleep(200);

            // UDP 发送端: 扔出去就完事,不管对方收没收到
            try (DatagramSocket sender = new DatagramSocket()) {
                String msg = "这是一条 UDP 消息,不需要握手!";
                byte[] data = msg.getBytes(StandardCharsets.UTF_8);
                DatagramPacket packet = new DatagramPacket(
                        data, data.length, InetAddress.getByName("127.0.0.1"), 19999);
                sender.send(packet);
                System.out.println("已发送 UDP 包裹(" + data.length + " 字节),发送方不等待确认");
            }

            receiver.join(2000);
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制网络: " + e.getMessage());
            System.out.println("请复制代码到本地运行");
        }
    }
}

import com.sun.net.httpserver.HttpServer;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        HttpServer server = null;
        try {
            // 1. JDK 内置迷你 HTTP 服务器(教学用,生产别用)
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 17777), 0);
            server.createContext("/api/hello", exchange -> {
                String name = exchange.getRequestHeaders().getFirst("X-User");
                String body = "{\"message\":\"你好, " + (name == null ? "访客" : name) + "\"}";
                byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
                exchange.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
                exchange.sendResponseHeaders(200, bytes.length);
                try (OutputStream os = exchange.getResponseBody()) {
                    os.write(bytes);
                }
            });
            server.start();
            System.out.println("本地 HTTP 服务已启动: http://127.0.0.1:17777");

            // 2. HttpClient 同步 GET(带自定义 Header)
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest getReq = HttpRequest.newBuilder()
                    .uri(URI.create("http://127.0.0.1:17777/api/hello"))
                    .header("X-User", "Zhang-San") // HTTP 头值必须是 ASCII,中文需先 URL 编码
                    .GET()
                    .build();
            HttpResponse<String> resp = client.send(getReq, HttpResponse.BodyHandlers.ofString());
            System.out.println("同步 GET -> " + resp.statusCode() + " " + resp.body());

            // 3. 异步 POST: CompletableFuture 链式处理
            HttpRequest postReq = HttpRequest.newBuilder()
                    .uri(URI.create("http://127.0.0.1:17777/api/hello"))
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString("{\"course\":\"java\"}"))
                    .build();
            client.sendAsync(postReq, HttpResponse.BodyHandlers.ofString())
                    .thenApply(HttpResponse::body)
                    .thenAccept(body -> System.out.println("异步 POST -> " + body))
                    .join(); // 教学演示: 等待异步完成

            // 4. 访问真实外网请把 URI 换成 https://www.baidu.com(沙箱无外网,本地可用)
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制网络: " + e.getMessage());
            System.out.println("请复制代码到本地运行");
        } finally {
            if (server != null) server.stop(0);
        }
    }
}

public class Main {

    // 1. 饿汉式: 类加载即创建
    static class EagerSingleton {
        private static final EagerSingleton INSTANCE = new EagerSingleton();
        private EagerSingleton() {}
        public static EagerSingleton getInstance() { return INSTANCE; }
    }

    // 2. 双重检查锁: volatile 防止指令重排导致拿到"半初始化"对象
    static class DclSingleton {
        private static volatile DclSingleton instance;
        private DclSingleton() {}
        public static DclSingleton getInstance() {
            if (instance == null) {                    // 第一次检查(无锁,快)
                synchronized (DclSingleton.class) {
                    if (instance == null) {            // 第二次检查(持锁,准)
                        instance = new DclSingleton();
                    }
                }
            }
            return instance;
        }
    }

    // 3. 静态内部类: 类加载机制保证线程安全 + 懒加载
    static class HolderSingleton {
        private HolderSingleton() {}
        private static class Holder {
            static final HolderSingleton INSTANCE = new HolderSingleton();
        }
        public static HolderSingleton getInstance() { return Holder.INSTANCE; }
    }

    // 4. 枚举单例: 终极答案(防反射、防序列化)
    enum EnumSingleton {
        INSTANCE;
        public void hello() { System.out.println("枚举单例: 我是唯一!"); }
    }

    public static void main(String[] args) throws InterruptedException {
        // 多线程并发获取,验证都是同一实例
        Object[] results = new Object[10];
        Thread[] ts = new Thread[10];
        for (int i = 0; i < 10; i++) {
            int idx = i;
            ts[i] = new Thread(() -> results[idx] = DclSingleton.getInstance());
            ts[i].start();
        }
        for (Thread t : ts) t.join();

        boolean allSame = true;
        for (int i = 1; i < results.length; i++) {
            if (results[i] != results[0]) allSame = false;
        }
        System.out.println("DCL 单例: 10 个线程拿到同一实例? " + allSame);
        System.out.println("饿汉式 identityHash: " + System.identityHashCode(EagerSingleton.getInstance()));
        System.out.println("内部类 identityHash: " + System.identityHashCode(HolderSingleton.getInstance()));
        EnumSingleton.INSTANCE.hello();
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;

public class Main {

    // ---- 产品族: 支付接口与实现 ----
    interface Pay {
        void pay(int amount);
    }
    static class WechatPay implements Pay {
        public void pay(int amount) { System.out.println("微信支付 " + amount + " 元"); }
    }
    static class Alipay implements Pay {
        public void pay(int amount) { System.out.println("支付宝支付 " + amount + " 元"); }
    }

    // ---- 简单工厂: switch 版(新增类型要改这里) ----
    static class SimplePayFactory {
        static Pay create(String type) {
            return switch (type) {
                case "wechat" -> new WechatPay();
                case "alipay" -> new Alipay();
                default -> throw new IllegalArgumentException("未知支付: " + type);
            };
        }
    }

    // ---- 注册表工厂: Map + Supplier(新增类型只需注册,不改工厂) ----
    static class PayRegistry {
        private static final Map<String, Supplier<Pay>> REGISTRY = new HashMap<>();
        static void register(String type, Supplier<Pay> supplier) {
            REGISTRY.put(type, supplier);
        }
        static Pay create(String type) {
            Supplier<Pay> s = REGISTRY.get(type);
            if (s == null) throw new IllegalArgumentException("未注册的支付: " + type);
            return s.get();
        }
    }

    public static void main(String[] args) {
        // 初始化注册
        PayRegistry.register("wechat", WechatPay::new);
        PayRegistry.register("alipay", Alipay::new);

        // 使用方完全不知道具体类
        PayRegistry.create("wechat").pay(100);
        SimplePayFactory.create("alipay").pay(200);

        // 扩展演示: 新增"云闪付",注册表一行搞定,工厂代码零修改!
        class UnionPay implements Pay {
            public void pay(int amount) { System.out.println("云闪付支付 " + amount + " 元"); }
        }
        PayRegistry.register("unionpay", UnionPay::new);
        PayRegistry.create("unionpay").pay(300);

        System.out.println("对照思考: Spring 的 @Service 注解 = register,getBean = create");
    }
}

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {

    /** 事件对象 */
    record OrderEvent(String orderId, int amount, String user) {}

    /** 监听器接口(观察者) */
    interface EventListener<T> {
        void onEvent(T event);
    }

    /** 迷你事件总线(发布-订阅,双方互不相识) */
    static class EventBus {
        // CopyOnWriteArrayList: 读多写少,遍历时注册新监听器也安全
        private final Map<Class<?>, List<EventListener<?>>> listeners = new ConcurrentHashMap<>();

        <T> void subscribe(Class<T> eventType, EventListener<T> listener) {
            listeners.computeIfAbsent(eventType, k -> new CopyOnWriteArrayList<>()).add(listener);
        }

        @SuppressWarnings("unchecked")
        <T> void publish(T event) {
            List<EventListener<?>> list = listeners.getOrDefault(event.getClass(), List.of());
            for (EventListener<?> l : list) {
                ((EventListener<T>) l).onEvent(event);
            }
        }
    }

    public static void main(String[] args) {
        EventBus bus = new EventBus();

        // 三个监听器各自订阅,互不知道对方存在
        bus.subscribe(OrderEvent.class, e ->
                System.out.println("[积分服务] 用户 " + e.user() + " 获得 " + e.amount() + " 积分"));
        bus.subscribe(OrderEvent.class, e ->
                System.out.println("[库存服务] 订单 " + e.orderId() + " 锁定库存"));
        bus.subscribe(OrderEvent.class, e ->
                System.out.println("[消息服务] 给用户 " + e.user() + " 发送下单成功通知"));

        // 业务代码只负责发布事件——一行搞定,不关心谁在处理
        System.out.println("--- 用户下单 ---");
        bus.publish(new OrderEvent("NO-10086", 299, "小明"));

        System.out.println("--- 又一个订单 ---");
        bus.publish(new OrderEvent("NO-10087", 59, "小红"));

        System.out.println("对照思考: Spring 的 publishEvent + @EventListener 就是这个 EventBus");
    }
}

import java.util.HashMap;
import java.util.Map;

public class Main {

    /** 策略接口: 满减折扣算法(函数式接口,Lambda 可直接当策略) */
    @FunctionalInterface
    interface Discount {
        int apply(int originalPrice);
    }

    /** 策略注册表: 策略名 -> 策略实现 */
    static final Map<String, Discount> STRATEGIES = new HashMap<>();
    static {
        STRATEGIES.put("原价",   p -> p);
        STRATEGIES.put("九折",   p -> p * 90 / 100);
        STRATEGIES.put("满300减50", p -> p >= 300 ? p - 50 : p);
        STRATEGIES.put("VIP折上折", p -> (int) (p * 0.8 * 0.95));
    }

    /** 结算上下文: 持有并执行策略 */
    static int checkout(String strategyName, int price) {
        Discount d = STRATEGIES.get(strategyName);
        if (d == null) throw new IllegalArgumentException("未知策略: " + strategyName);
        return d.apply(price);
    }

    public static void main(String[] args) {
        int price = 500;
        System.out.println("原价 " + price + " 元,各策略结算价:");
        STRATEGIES.forEach((name, d) ->
                System.out.printf("  %-10s -> %d 元%n", name, d.apply(price)));

        // 运行时切换策略(比如根据用户等级)
        String userLevel = "VIP";
        String chosen = userLevel.equals("VIP") ? "VIP折上折" : "九折";
        System.out.println("VIP 用户实际支付: " + checkout(chosen, price) + " 元");

        // 扩展演示: 新增"第二件半价"策略 = 注册一行,老代码零修改
        STRATEGIES.put("第二件半价", p -> p - p / 4); // 假设两件同价商品
        System.out.println("新策略[第二件半价] -> " + checkout("第二件半价", price) + " 元");

        System.out.println("反面对照: 用 if-else 写,每加一个策略就要改结算方法,规则多了必失控");
    }
}

public class Main {

    /** 组件接口 */
    interface Coffee {
        String description();
        int cost();
    }

    /** 具体组件: 美式咖啡 */
    static class Americano implements Coffee {
        public String description() { return "美式咖啡"; }
        public int cost() { return 20; }
    }

    /** 装饰器基类: 实现同一接口,持有被装饰者 */
    static abstract class CoffeeDecorator implements Coffee {
        protected final Coffee coffee;
        CoffeeDecorator(Coffee coffee) { this.coffee = coffee; }
    }

    static class Milk extends CoffeeDecorator {
        Milk(Coffee c) { super(c); }
        public String description() { return coffee.description() + " + 牛奶"; }
        public int cost() { return coffee.cost() + 5; }
    }

    static class Sugar extends CoffeeDecorator {
        Sugar(Coffee c) { super(c); }
        public String description() { return coffee.description() + " + 糖"; }
        public int cost() { return coffee.cost() + 2; }
    }

    static class Ice extends CoffeeDecorator {
        Ice(Coffee c) { super(c); }
        public String description() { return coffee.description() + " + 加冰"; }
        public int cost() { return coffee.cost() + 0; }
    }

    public static void main(String[] args) {
        // 基础款
        Coffee c1 = new Americano();
        System.out.println(c1.description() + " = " + c1.cost() + " 元");

        // 层层包装: 能力自由组合
        Coffee c2 = new Milk(new Sugar(new Americano()));
        System.out.println(c2.description() + " = " + c2.cost() + " 元");

        Coffee c3 = new Ice(new Milk(new Milk(new Americano())));
        System.out.println(c3.description() + " = " + c3.cost() + " 元");

        System.out.println();
        System.out.println("对照 Java IO:");
        System.out.println("  new BufferedInputStream(new FileInputStream(file))");
        System.out.println("  = 装饰器(缓冲) 包 组件(文件读取) —— 完全同一个模式!");
    }
}

public class Main {

    /** 审批请求 */
    record LeaveRequest(String employee, int days, String reason) {}

    /** 责任链 + 模板方法: 审批人抽象 */
    static abstract class Approver {
        protected Approver next; // 链条上的下一棒

        Approver setNext(Approver next) { this.next = next; return next; }

        /** 模板方法: 固定处理骨架,子类只实现"能否批"和"怎么批" */
        final void handle(LeaveRequest req) {
            if (canApprove(req)) {
                doApprove(req); // 可变步骤 1
            } else if (next != null) {
                System.out.println("  " + name() + ": 权限不足(" + maxDays() + "天),上报上级");
                next.handle(req); // 传给下一棒
            } else {
                System.out.println("  " + name() + ": 链条到头,没人能批,拒绝!");
            }
        }

        abstract boolean canApprove(LeaveRequest req); // 可变步骤 2
        abstract int maxDays();
        abstract String name();

        void doApprove(LeaveRequest req) {
            System.out.println("  " + name() + ": 批准 " + req.employee()
                    + " 请假 " + req.days() + " 天(" + req.reason() + ")");
        }
    }

    static class TeamLeader extends Approver {
        boolean canApprove(LeaveRequest r) { return r.days() <= 2; }
        int maxDays() { return 2; }
        String name() { return "组长"; }
    }
    static class Manager extends Approver {
        boolean canApprove(LeaveRequest r) { return r.days() <= 5; }
        int maxDays() { return 5; }
        String name() { return "经理"; }
    }
    static class Director extends Approver {
        boolean canApprove(LeaveRequest r) { return r.days() <= 15; }
        int maxDays() { return 15; }
        String name() { return "总监"; }
    }

    public static void main(String[] args) {
        // 组装责任链: 组长 -> 经理 -> 总监
        Approver chain = new TeamLeader();
        chain.setNext(new Manager()).setNext(new Director());

        LeaveRequest[] requests = {
            new LeaveRequest("小王", 1, "家里有事"),
            new LeaveRequest("小李", 4, "年假旅行"),
            new LeaveRequest("小张", 10, "婚假"),
            new LeaveRequest("老周", 30, "环球旅行"),
        };
        for (LeaveRequest r : requests) {
            System.out.println("申请: " + r.employee() + " 请假 " + r.days() + " 天");
            chain.handle(r);
        }
        System.out.println("对照思考: Servlet 的 FilterChain、Spring 拦截器链都是这个模式");
    }
}

import java.net.URLDecoder;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        // 1. Base64 编解码(编码,不是加密!)
        String secret = "我的密码abc123";
        String encoded = Base64.getEncoder()
                .encodeToString(secret.getBytes(StandardCharsets.UTF_8));
        System.out.println("原文:   " + secret);
        System.out.println("Base64: " + encoded);

        String decoded = new String(Base64.getDecoder().decode(encoded), StandardCharsets.UTF_8);
        System.out.println("解回:   " + decoded);
        System.out.println("> 任何人都能解回 -> Base64 只是编码,毫无保密性!");

        // 2. Base64 在 HTTP Basic 认证中的用法(用户名:密码)
        String credential = "admin:admin123";
        String basicAuth = Base64.getEncoder()
                .encodeToString(credential.getBytes(StandardCharsets.UTF_8));
        System.out.println("\nBasic 认证头: Authorization: Basic " + basicAuth);

        // 3. URL 编码: 中文与特殊字符必须转义
        String keyword = "Java 学习 & 实战";
        String urlEncoded = URLEncoder.encode(keyword, StandardCharsets.UTF_8);
        System.out.println("\nURL 编码: " + urlEncoded);
        System.out.println("URL 解码: " + URLDecoder.decode(urlEncoded, StandardCharsets.UTF_8));

        // 4. 不是所有空格都变加号: 路径段与查询参数的规则略有差异
        System.out.println("\n空格编码为 + 或 %20,取决于上下文(查询参数常用 +,路径用 %20)");
    }
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.HexFormat;

public class Main {

    /** 计算哈希(十六进制字符串) */
    static String hash(String algorithm, String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance(algorithm);
        byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
        return HexFormat.of().formatHex(digest);
    }

    public static void main(String[] args) throws Exception {
        String password = "admin123";

        // 1. 直接哈希: 相同密码 -> 相同结果,彩虹表可直接命中
        String md5 = hash("MD5", password);
        String sha256 = hash("SHA-256", password);
        System.out.println("MD5('admin123')    = " + md5);
        System.out.println("SHA256('admin123') = " + sha256);
        System.out.println("> 这两个值是公开的,搜索引擎一查就知道原文!\n");

        // 2. 加盐: 每个用户独立随机盐,结果完全不同
        byte[] salt1 = new byte[16], salt2 = new byte[16];
        new SecureRandom().nextBytes(salt1);
        new SecureRandom().nextBytes(salt2);
        System.out.println("用户A 加盐哈希: " + hashWithSalt(password, salt1));
        System.out.println("用户B 加盐哈希: " + hashWithSalt(password, salt2));
        System.out.println("> 同一个密码,两次结果不同 -> 彩虹表失效\n");

        // 3. 加盐 + 迭代(慢哈希): 暴力破解成本成倍上升
        long begin = System.currentTimeMillis();
        String slow = slowHash(password, salt1, 20000);
        long cost = System.currentTimeMillis() - begin;
        System.out.println("迭代 20000 次结果: " + slow.substring(0, 32) + "...");
        System.out.println("单次计算耗时 " + cost + "ms -> 破解成本被放大数万倍");
        System.out.println("\n生产建议: 用 BCrypt/PBKDF2/Argon2,别自己拼盐和迭代");
    }

    static String hashWithSalt(String password, byte[] salt) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(salt);                                            // 先混入盐
        return HexFormat.of().formatHex(md.digest(password.getBytes(StandardCharsets.UTF_8)));
    }

    static String slowHash(String password, byte[] salt, int iterations) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] data = password.getBytes(StandardCharsets.UTF_8);
        for (int i = 0; i < iterations; i++) {
            md.reset();
            md.update(salt);
            md.update(data);
            data = md.digest();
        }
        return HexFormat.of().formatHex(data);
    }
}

import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;

public class Main {
    public static void main(String[] args) throws Exception {
        String plainText = "用户手机号: 13812345678";

        // 1. 生成 AES 密钥(实际项目中安全保存,绝不硬编码!)
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(128);
        SecretKey key = kg.generateKey();
        System.out.println("AES 密钥(Base64): " + Base64.getEncoder().encodeToString(key.getEncoded()));

        // 2. 生成随机 IV(16 字节)
        byte[] iv = new byte[16];
        new SecureRandom().nextBytes(iv);

        // 3. 加密
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv));
        byte[] encrypted = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));
        String cipherText = Base64.getEncoder().encodeToString(encrypted);
        String ivBase64 = Base64.getEncoder().encodeToString(iv);
        System.out.println("\n密文(Base64): " + cipherText);
        System.out.println("IV(Base64):   " + ivBase64);

        // 4. 同样明文再加密一次 -> 密文不同(因为 IV 随机)
        byte[] iv2 = new byte[16];
        new SecureRandom().nextBytes(iv2);
        cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv2));
        String cipherText2 = Base64.getEncoder()
                .encodeToString(cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8)));
        System.out.println("\n同一明文第二次加密: " + cipherText2);
        System.out.println("> 密文不同,攻击者无法通过密文比对猜测内容\n");

        // 5. 解密(IV 必须与加密时一致)
        cipher.init(Cipher.DECRYPT_MODE, key, new IvParameterSpec(iv));
        byte[] decrypted = cipher.doFinal(Base64.getDecoder().decode(cipherText));
        System.out.println("解密还原: " + new String(decrypted, StandardCharsets.UTF_8));

        System.out.println("\n生产建议: 用 AES/GCM/NoPadding(GCM 自带防篡改),别用 ECB");
    }
}

import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.Signature;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        // 1. 生成 RSA 密钥对(演示用 1024 位;生产建议 2048 以上)
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
        kpg.initialize(1024);
        KeyPair keyPair = kpg.generateKeyPair();
        System.out.println("密钥对已生成: " + keyPair.getPublic().getAlgorithm()
                + " " + keyPair.getPublic().getEncoded().length * 8 + " 位(公钥)");

        String message = "转账 100 元给张三,订单号 NO-9527";

        // 2. 用私钥签名
        Signature signer = Signature.getInstance("SHA256withRSA");
        signer.initSign(keyPair.getPrivate());
        signer.update(message.getBytes(StandardCharsets.UTF_8));
        byte[] signature = signer.sign();
        String signatureB64 = Base64.getEncoder().encodeToString(signature);
        System.out.println("\n原文: " + message);
        System.out.println("签名(前 40 字符): " + signatureB64.substring(0, 40) + "...");

        // 3. 用公钥验证(任何人拿公钥都能验)
        Signature verifier = Signature.getInstance("SHA256withRSA");
        verifier.initVerify(keyPair.getPublic());
        verifier.update(message.getBytes(StandardCharsets.UTF_8));
        System.out.println("\n验证原始消息: " + (verifier.verify(signature) ? "通过 ✓" : "失败 ✗"));

        // 4. 篡改消息 -> 验证失败(这就是"防篡改")
        String tampered = "转账 10000 元给张三,订单号 NO-9527";
        Signature verifier2 = Signature.getInstance("SHA256withRSA");
        verifier2.initVerify(keyPair.getPublic());
        verifier2.update(tampered.getBytes(StandardCharsets.UTF_8));
        System.out.println("验证被篡改的消息: " + (verifier2.verify(signature) ? "通过 ✓" : "失败 ✗"));
        System.out.println("> 金额从 100 改成 10000,签名立刻失效\n");

        System.out.println("HTTPS 类比: 服务器证书 = 公钥 + CA 签名;");
        System.out.println("客户端验证 CA 签名 -> 确认服务器身份 -> 再协商会话密钥");
    }
}

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {

    /** 迷你 JSON 工具: 只支持 Map/List/String/Number/Boolean/null(教学版) */
    static class MiniJson {

        // ---------- 序列化 ----------
        static String toJson(Object o) {
            StringBuilder sb = new StringBuilder();
            write(sb, o);
            return sb.toString();
        }

        @SuppressWarnings("unchecked")
        private static void write(StringBuilder sb, Object o) {
            if (o == null) { sb.append("null"); return; }
            if (o instanceof String s) { sb.append('"').append(escape(s)).append('"'); return; }
            if (o instanceof Number || o instanceof Boolean) { sb.append(o); return; }
            if (o instanceof Map<?, ?> map) {
                sb.append('{');
                boolean first = true;
                for (Map.Entry<?, ?> e : map.entrySet()) {
                    if (!first) sb.append(',');
                    first = false;
                    sb.append('"').append(escape(String.valueOf(e.getKey()))).append("\":");
                    write(sb, e.getValue());
                }
                sb.append('}');
                return;
            }
            if (o instanceof List<?> list) {
                sb.append('[');
                for (int i = 0; i < list.size(); i++) {
                    if (i > 0) sb.append(',');
                    write(sb, list.get(i));
                }
                sb.append(']');
                return;
            }
            // 其他类型(如自定义对象)降级为字符串
            sb.append('"').append(escape(o.toString())).append('"');
        }

        private static String escape(String s) {
            return s.replace("\\", "\\\\").replace("\"", "\\\"")
                    .replace("\n", "\\n").replace("\t", "\\t");
        }

        // ---------- 反序列化 ----------
        static Object parse(String json) {
            return new Parser(json).parseValue();
        }

        static class Parser {
            final String s; int i = 0;
            Parser(String s) { this.s = s; }
            void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }

            Object parseValue() {
                ws();
                char c = s.charAt(i);
                return switch (c) {
                    case '{' -> parseObject();
                    case '[' -> parseArray();
                    case '"' -> parseString();
                    case 't' -> { i += 4; yield Boolean.TRUE; }
                    case 'f' -> { i += 5; yield Boolean.FALSE; }
                    case 'n' -> { i += 4; yield null; }
                    default  -> parseNumber();
                };
            }

            Map<String, Object> parseObject() {
                Map<String, Object> map = new LinkedHashMap<>();
                i++; // {
                ws();
                if (s.charAt(i) == '}') { i++; return map; }
                while (true) {
                    ws();
                    String key = parseString();
                    ws(); i++; // :
                    map.put(key, parseValue());
                    ws();
                    if (s.charAt(i) == ',') { i++; continue; }
                    i++; // }
                    return map;
                }
            }

            List<Object> parseArray() {
                List<Object> list = new ArrayList<>();
                i++; // [
                ws();
                if (s.charAt(i) == ']') { i++; return list; }
                while (true) {
                    list.add(parseValue());
                    ws();
                    if (s.charAt(i) == ',') { i++; continue; }
                    i++; // ]
                    return list;
                }
            }

            String parseString() {
                StringBuilder sb = new StringBuilder();
                i++; // 开引号
                while (s.charAt(i) != '"') {
                    char c = s.charAt(i);
                    if (c == '\\') {
                        i++;
                        char esc = s.charAt(i);
                        sb.append(switch (esc) {
                            case 'n' -> '\n'; case 't' -> '\t';
                            case 'r' -> '\r'; case '"' -> '"';
                            case '\\' -> '\\'; default -> esc;
                        });
                    } else sb.append(c);
                    i++;
                }
                i++; // 闭引号
                return sb.toString();
            }

            Object parseNumber() {
                int start = i;
                while (i < s.length() && "-+.eE0123456789".indexOf(s.charAt(i)) >= 0) i++;
                String num = s.substring(start, i);
                return num.contains(".") || num.contains("e") || num.contains("E")
                        ? (Object) Double.parseDouble(num) : (Object) Long.parseLong(num);
            }
        }
    }

    public static void main(String[] args) {
        // 1. 序列化: 嵌套结构
        Map<String, Object> user = new LinkedHashMap<>();
        user.put("id", 1001);
        user.put("name", "张三");
        user.put("vip", true);
        user.put("tags", List.of("Java", "后端"));
        user.put("address", Map.of("city", "深圳", "zip", "518000"));

        String json = MiniJson.toJson(user);
        System.out.println("序列化结果:");
        System.out.println("  " + json);

        // 2. 反序列化: 还原为 Map/List
        Object parsed = MiniJson.parse(json);
        System.out.println("\n反序列化类型: " + parsed.getClass().getSimpleName());
        @SuppressWarnings("unchecked")
        Map<String, Object> back = (Map<String, Object>) parsed;
        System.out.println("  name = " + back.get("name") + " (" + back.get("name").getClass().getSimpleName() + ")");
        System.out.println("  id   = " + back.get("id") + " (" + back.get("id").getClass().getSimpleName() + ")");
        System.out.println("  tags = " + back.get("tags"));

        // 3. 转义测试
        String tricky = MiniJson.toJson(Map.of("msg", "他说:\"你好\"\n换行了"));
        System.out.println("\n转义测试: " + tricky);
        System.out.println("解析回来: " + ((Map<?, ?>) MiniJson.parse(tricky)).get("msg"));
    }
}

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

public class Main {
    public static void main(String[] args) throws Exception {
        String xml = """
                <?xml version="1.0" encoding="UTF-8"?>
                <class name="Java 一班">
                    <student id="1001">
                        <name>张三</name>
                        <score>92</score>
                    </student>
                    <student id="1002">
                        <name>李四</name>
                        <score>78</score>
                    </student>
                    <student id="1003">
                        <name>王五</name>
                        <score>85</score>
                    </student>
                </class>
                """;

        // 1. 创建解析器(生产环境务必禁用 DTD 防 XXE 攻击)
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (Exception ignore) { }
        DocumentBuilder builder = factory.newDocumentBuilder();

        // 2. 解析为 DOM 树
        Document doc = builder.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));
        Element root = doc.getDocumentElement();
        System.out.println("根元素: " + root.getTagName()
                + " (name=" + root.getAttribute("name") + ")");

        // 3. 遍历节点
        NodeList students = doc.getElementsByTagName("student");
        System.out.println("\n共 " + students.getLength() + " 名学生:");
        int total = 0, max = 0;
        String topName = "";
        for (int i = 0; i < students.getLength(); i++) {
            Element student = (Element) students.item(i);
            String id = student.getAttribute("id");
            Element nameEl = (Element) student.getElementsByTagName("name").item(0);
            Element scoreEl = (Element) student.getElementsByTagName("score").item(0);
            int score = Integer.parseInt(scoreEl.getTextContent());
            total += score;
            if (score > max) { max = score; topName = nameEl.getTextContent(); }
            System.out.printf("  学号 %s | %s | %d 分%n", id, nameEl.getTextContent(), score);
        }
        System.out.printf("%n平均分: %.1f,最高分: %s (%d)%n",
                (double) total / students.getLength(), topName, max);

        System.out.println("\n对照: pom.xml、Spring 老配置文件的解析就是这样进行的");
    }
}

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;

public class Main {

    /** 模拟 Jackson 的行为: 按注解规则把对象转成 JSON(简化版) */
    static class User {
        Long id;
        String userName;              // Java 驼峰
        String passwordHash;          // 敏感,不序列化
        String email;
        String nickname;              // null,不输出

        User(Long id, String userName, String passwordHash, String email) {
            this.id = id; this.userName = userName;
            this.passwordHash = passwordHash; this.email = email;
        }
    }

    /** 极简"序列化器": 按规则挑字段 */
    static String serialize(Object obj) throws Exception {
        Map<String, Object> map = new LinkedHashMap<>();
        for (Field f : obj.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            Object value = f.get(obj);

            // 规则1: 密码类字段忽略(对照 @JsonIgnore)
            if (f.getName().toLowerCase().contains("password")) continue;
            // 规则2: null 不输出(对照 @JsonInclude(NON_NULL))
            if (value == null) continue;
            // 规则3: 驼峰转下划线(对照 @JsonProperty)
            String key = camelToSnake(f.getName());
            map.put(key, value);
        }
        // 拼接 JSON
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<String, Object> e : map.entrySet()) {
            if (!first) sb.append(',');
            first = false;
            Object v = e.getValue();
            sb.append('"').append(e.getKey()).append("\":");
            sb.append(v instanceof Number ? v : "\"" + v + "\"");
        }
        return sb.append('}').toString();
    }

    static String camelToSnake(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) sb.append('_').append(Character.toLowerCase(c));
            else sb.append(c);
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        User user = new User(1001L, "zhangsan", "$2a$10$abcdef...", "zs@example.com");

        System.out.println("原始字段: id / userName / passwordHash / email / nickname(null)");
        System.out.println("序列化结果:");
        System.out.println("  " + serialize(user));

        System.out.println("\n关键点:");
        System.out.println("  1. userName -> user_name (驼峰转下划线,对照 @JsonProperty)");
        System.out.println("  2. passwordHash 消失 (对照 @JsonIgnore,安全要点!)");
        System.out.println("  3. nickname 为 null 不输出 (对照 @JsonInclude(NON_NULL))");
        System.out.println("  4. 真实项目用 Jackson: objectMapper.writeValueAsString(user)");

        System.out.println("\n本项目实践: Controller 返回 Result.ok(data),Spring 自动完成上述序列化");
    }
}

