        demo.setDaemon(true);
        demo.start();
        try {
            demo.join(3000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        if (demo.isAlive()) {
            System.out.println("\n[提示] 当前环境限制了本地端口/网络访问,演示未完成");
            System.out.println("请把代码复制到本地 IDE 运行,效果相同");
        }
    }

    static void runDemo() {
