        try {
            // 1. 启动一个迷你 HTTP 服务器 /api/hello
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 18080), 0);
            server.createContext("/api/hello", exchange -> {
                System.out.println("--- 服务器收到的请求 ---");
                System.out.println(exchange.getRequestMethod() + " " + exchange.getRequestURI());
                exchange.getRequestHeaders().forEach((k, v) ->
                        System.out.println(k + ": " + String.join(",", v)));
                String body = "{\"code\":0,\"message\":\"success\",\"data\":\"Hello HTTP\"}";
                byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
                exchange.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
                exchange.sendResponseHeaders(200, bytes.length);
