import com.sun.net.httpserver.HttpServer;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;

public class Main {

    /** 迷你 Servlet 抽象: 对应 javax.servlet.Servlet 接口 */
    interface MiniServlet {
        default void init() { System.out.println("  [容器] " + getClass().getSimpleName() + ".init() 只调用一次"); }
        void service(String path, String method); // 不抛受检异常,便于在 lambda 内调用
        default void destroy() { System.out.println("  [容器] " + getClass().getSimpleName() + ".destroy() 容器关闭时调用"); }
    }

    static class HelloServlet implements MiniServlet {
        // 注意: 下面这个计数器展示"单例多线程"——真实开发不要这样存请求状态
        private int callCount = 0;
        public void service(String path, String method) {
            synchronized (this) { callCount++; }
            System.out.println("  [Servlet] 处理请求 " + method + " " + path
                    + " (第 " + callCount + " 次调用, 线程: " + Thread.currentThread().getName() + ")");
        }
    }

    public static void main(String[] args) throws Exception {
        // 1. 容器启动: 注册 Servlet 并初始化
        Map<String, MiniServlet> mappings = new ConcurrentHashMap<>();
        HelloServlet hello = new HelloServlet();
        hello.init(); // 生命周期: 只初始化一次
        mappings.put("/hello", hello);
        mappings.put("/bye", new HelloServlet());

        // 2. 容器用线程池处理并发请求(与 Tomcat 一致)
        var pool = Executors.newFixedThreadPool(3);
        HttpServer server = null;
        try {
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 18081), 0);
            HttpServer finalServer = server;
            server.createContext("/", exchange -> {
                String path = exchange.getRequestURI().getPath();
                MiniServlet servlet = mappings.get(path);
                String body;
                if (servlet == null) {
                    body = "404 Not Found (容器找不到映射)";
                    exchange.sendResponseHeaders(404, body.getBytes(StandardCharsets.UTF_8).length);
                } else {
                    servlet.service(path, exchange.getRequestMethod());
                    body = "OK from " + path;
                    exchange.sendResponseHeaders(200, body.getBytes(StandardCharsets.UTF_8).length);
                }
                try (OutputStream os = exchange.getResponseBody()) {
                    os.write(body.getBytes(StandardCharsets.UTF_8));
                }
            });
            server.setExecutor(pool); // 请求交给线程池
            server.start();
            Thread.sleep(200);
            System.out.println("[容器] 启动完成,端口 18081\n");

            // 3. 模拟客户端并发访问
            var client = java.net.http.HttpClient.newHttpClient();
            for (String p : new String[]{"/hello", "/hello", "/bye", "/not-exist"}) {
                var resp = client.send(
                        java.net.http.HttpRequest.newBuilder(
                                java.net.URI.create("http://127.0.0.1:18081" + p)).build(),
                        java.net.http.HttpResponse.BodyHandlers.ofString());
                System.out.println("客户端 " + p + " -> " + resp.statusCode() + " " + resp.body());
            }
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制端口绑定: " + e.getMessage());
        } finally {
            // 4. 容器关闭: 销毁所有 Servlet
            System.out.println("\n[容器] 准备关闭...");
            mappings.values().forEach(MiniServlet::destroy);
            if (server != null) server.stop(0);
            pool.shutdown();
        }
    }
}

import com.sun.net.httpserver.HttpServer;
import java.lang.annotation.*;
import java.lang.reflect.Method;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {

    // ---------- 1. 定义注解(对照 Spring 的 @RestController / @GetMapping) ----------
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface GetMapping { String value(); }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.TYPE)
    @interface RestController { }

    // ---------- 2. 控制器(对照本项目 LearningController) ----------
    @RestController
    static class UserController {
        @GetMapping("/api/users")
        public String list() {
            return "{\"code\":0,\"data\":[\"张三\",\"李四\"]}";
        }

        @GetMapping("/api/users/{id}")
        public String detail(String id) {
            return "{\"code\":0,\"data\":{\"id\":" + id + ",\"name\":\"用户" + id + "\"}}";
        }
    }

    // ---------- 3. 迷你 DispatcherServlet: 扫描注解 + 建路由表 + 分发 ----------
    static class MiniDispatcher {
        record Route(Pattern pattern, List<String> vars, Method method, Object handler) { }
        final List<Route> routes = new ArrayList<>();

        void register(Object controller) {
            if (!controller.getClass().isAnnotationPresent(RestController.class)) return;
            for (Method m : controller.getClass().getDeclaredMethods()) {
                GetMapping mapping = m.getAnnotation(GetMapping.class);
                if (mapping == null) continue;
                // 把 /api/users/{id} 编译成正则,同时记录变量名
                List<String> vars = new ArrayList<>();
                StringBuilder regexSb = new StringBuilder();
                Matcher matcher = Pattern.compile("\\{([^/]+)\\}").matcher(mapping.value());
                while (matcher.find()) {
                    vars.add(matcher.group(1));
                    matcher.appendReplacement(regexSb, "([^/]+)");
                }
                matcher.appendTail(regexSb);
                String regex = regexSb.toString();
                routes.add(new Route(Pattern.compile("^" + regex + "$"), vars, m, controller));
                System.out.println("  [路由注册] GET " + mapping.value()
                        + " -> " + controller.getClass().getSimpleName() + "#" + m.getName());
            }
        }

        String dispatch(String httpMethod, String path) {
            for (Route r : routes) {
                Matcher matcher = r.pattern().matcher(path);
                if (!matcher.matches()) continue;
                try {
                    Object[] args = new Object[r.vars().size()];
                    for (int i = 0; i < args.length; i++) args[i] = matcher.group(i + 1);
                    return (String) r.method().invoke(r.handler(), args);
                } catch (Exception e) {
                    return "{\"code\":500,\"message\":\"服务器内部错误\"}";
                }
            }
            return "{\"code\":404,\"message\":\"没有匹配的路由\"}";
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("[启动] 扫描控制器,建立路由表:");
        MiniDispatcher dispatcher = new MiniDispatcher();
        dispatcher.register(new UserController());

        HttpServer server = null;
        try {
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 18082), 0);
            server.createContext("/", exchange -> {
                String path = exchange.getRequestURI().getPath();
                String body = dispatcher.dispatch(exchange.getRequestMethod(), path);
                byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
                exchange.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
                exchange.sendResponseHeaders(200, bytes.length);
                try (var os = exchange.getResponseBody()) { os.write(bytes); }
            });
            server.start();
            Thread.sleep(200);

            System.out.println("\n[测试] 模拟客户端请求:");
            var client = java.net.http.HttpClient.newHttpClient();
            for (String p : new String[]{"/api/users", "/api/users/42", "/api/orders"}) {
                var resp = client.send(java.net.http.HttpRequest.newBuilder(
                                java.net.URI.create("http://127.0.0.1:18082" + p)).build(),
                        java.net.http.HttpResponse.BodyHandlers.ofString());
                System.out.println("  GET " + p);
                System.out.println("    -> " + resp.body());
            }
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制端口绑定: " + e.getMessage());
        } finally {
            if (server != null) server.stop(0);
        }

        System.out.println("\n这就是 Spring MVC 的核心机制:");
        System.out.println("  @GetMapping 注解 -> 扫描建路由表 -> 按路径匹配 -> 提取路径变量 -> 反射调用");
    }
}

import java.lang.annotation.*;
import java.lang.reflect.Field;
import java.util.*;

public class Main {

    // ---------- 注解(对照 Spring 的 @Component / @Autowired) ----------
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.TYPE)
    @interface Component { }

    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD)
    @interface Autowired { }

    @Component
    static class UserRepository {
        public String findById(long id) { return "用户#" + id + " 张三"; }
    }

    @Component
    static class ScoreRepository {
        public int scoreOf(long id) { return 88; }
    }

    @Component
    static class UserService {
        @Autowired private UserRepository userRepository;
        @Autowired private ScoreRepository scoreRepository;

        public String describe(long id) {
            if (userRepository == null) return "依赖未注入!";
            return userRepository.findById(id) + ", 成绩 " + scoreRepository.scoreOf(id);
        }
    }

    // ---------- 迷你 IoC 容器 ----------
    static class MiniApplicationContext {
        private final Map<Class<?>, Object> beans = new HashMap<>();

        MiniApplicationContext(Class<?>... candidates) {
            // 第 1 步: 扫描 -> 实例化
            for (Class<?> c : candidates) {
                if (c.isAnnotationPresent(Component.class)) {
                    try {
                        Object instance = c.getDeclaredConstructor().newInstance();
                        beans.put(c, instance);
                        System.out.println("  [容器] 实例化 " + c.getSimpleName());
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                }
            }
            // 第 2 步: 注入 @Autowired 字段
            for (Object bean : beans.values()) {
                for (Field f : bean.getClass().getDeclaredFields()) {
                    if (!f.isAnnotationPresent(Autowired.class)) continue;
                    Object dependency = beans.get(f.getType());
                    if (dependency == null) {
                        throw new IllegalStateException("找不到依赖: " + f.getType().getSimpleName());
                    }
                    f.setAccessible(true);
                    try { f.set(bean, dependency); } catch (Exception e) { throw new RuntimeException(e); }
                    System.out.println("  [容器] 注入 " + bean.getClass().getSimpleName()
                            + "." + f.getName() + " <- " + dependency.getClass().getSimpleName());
                }
            }
        }

        <T> T getBean(Class<T> type) { return type.cast(beans.get(type)); }
    }

    public static void main(String[] args) {
        System.out.println("[启动] 扫描并装配 Bean:");
        MiniApplicationContext ctx = new MiniApplicationContext(
                UserRepository.class, ScoreRepository.class, UserService.class);

        System.out.println("\n[使用] 从容器取 Bean 并调用:");
        UserService service = ctx.getBean(UserService.class);
        System.out.println("  " + service.describe(1001));
        System.out.println("  " + service.describe(1002));

        System.out.println("\n[验证] 单例: 两次 getBean 是同一对象? "
                + (ctx.getBean(UserService.class) == service));

        System.out.println("\n对照 Spring: @SpringBootApplication 启动时做的就是上述过程,");
        System.out.println("只是支持了构造器注入、循环依赖、AOP 代理、作用域等更多细节");
    }
}

public class Main {

    // ---------- 依赖接口与两种实现 ----------
    interface SmsSender {
        String send(String msg);
    }
    static class RealSmsSender implements SmsSender {
        public String send(String msg) { return "真实短信已发送: " + msg; }
    }
    /** 测试替身(Mock): 不发真短信,只记录 */
    static class MockSmsSender implements SmsSender {
        String lastMessage;
        public String send(String msg) { this.lastMessage = msg; return "MOCK"; }
    }

    // ---------- 字段注入风格(对照 @Autowired 私有字段) ----------
    static class OrderServiceFieldInjection {
        // private @Autowired SmsSender smsSender;  // 无法从外部设置 -> 测试困难
        private SmsSender smsSender = new RealSmsSender(); // 只能硬编码真实实现
        public String placeOrder() { return "下单成功; " + smsSender.send("您的订单已创建"); }
    }

    // ---------- 构造器注入风格(Spring 官方推荐) ----------
    static class OrderServiceConstructorInjection {
        private final SmsSender smsSender; // final: 不可变,线程安全
        OrderServiceConstructorInjection(SmsSender smsSender) { this.smsSender = smsSender; }
        public String placeOrder() { return "下单成功; " + smsSender.send("您的订单已创建"); }
    }

    public static void main(String[] args) {
        System.out.println("--- 字段注入: 只能跑真实实现 ---");
        System.out.println("  " + new OrderServiceFieldInjection().placeOrder());
        System.out.println("  问题: 想替换成 Mock 只能改源码/用反射,单测成本高,依赖关系也不显式\n");

        System.out.println("--- 构造器注入: 生产用真实实现 ---");
        var prod = new OrderServiceConstructorInjection(new RealSmsSender());
        System.out.println("  " + prod.placeOrder());

        System.out.println("\n--- 构造器注入: 测试用 Mock(一行搞定) ---");
        MockSmsSender mock = new MockSmsSender();
        var underTest = new OrderServiceConstructorInjection(mock);
        String result = underTest.placeOrder();
        System.out.println("  调用结果: " + result);
        System.out.println("  Mock 捕获到的消息: " + mock.lastMessage);
        System.out.println("  断言: 下单后应发送通知 -> " + (mock.lastMessage.contains("订单") ? "通过 ✓" : "失败 ✗"));

        System.out.println("\n结论: 构造器注入让依赖显式化、可 final、易测试 —— 这就是官方推荐的理由");
        System.out.println("对照本项目: UserServiceTest 用容器 + 真实 SQLite 测试,也可改为构造器注入 + Mock 提速");
    }
}

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

interface UserService {
    void save(String user);
}

public class Main {
    public static void main(String[] args) {
        UserService target = user -> System.out.println("业务: 保存 " + user);

        // JDK 动态代理: 在不改业务代码的前提下织入横切逻辑(日志/耗时)
        UserService proxy = (UserService) Proxy.newProxyInstance(
            Main.class.getClassLoader(),
            new Class[]{UserService.class},
            (proxyObj, method, args2) -> {
                long t = System.nanoTime();
                System.out.println("[AOP] " + method.getName() + " 开始");
                Object r = method.invoke(target, args2);
                System.out.println("[AOP] " + method.getName() + " 耗时 "
                    + (System.nanoTime() - t) / 1000 + "us");
                return r;
            });

        proxy.save("张三");
    }
}

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

interface AccountDao {
    void transfer(String from, String to, double amount);
}

public class Main {
    static final List<String> TX_LOG = new ArrayList<>();

    public static void main(String[] args) {
        AccountDao dao = (from, to, amount) ->
            System.out.println("业务: " + from + " -> " + to + " " + amount);

        // 用代理模拟 @Transactional: 方法前 BEGIN, 正常 COMMIT, 异常 ROLLBACK
        AccountDao tx = (AccountDao) Proxy.newProxyInstance(
            Main.class.getClassLoader(), new Class[]{AccountDao.class},
            (p, m, a) -> {
                TX_LOG.add("BEGIN");
                try {
                    Object r = m.invoke(dao, a);
                    TX_LOG.add("COMMIT");
                    return r;
                } catch (Exception e) {
                    TX_LOG.add("ROLLBACK: " + e.getCause().getMessage());
                    throw e;
                }
            });

        tx.transfer("张三", "李四", 100);
        System.out.println("事务日志: " + TX_LOG);
        System.out.println("经典陷阱: 同类内部自调用不走代理, 事务会失效!");
    }
}

import java.util.*;

public class Main {

    /** 模拟 Spring 的 @Conditional 条件评估器 */
    static class ConditionEvaluator {
        Set<String> classpath = new HashSet<>();   // 类路径上有什么(模拟)
        Set<String> existingBeans = new HashSet<>(); // 容器里已有什么 Bean

        boolean onClass(String className) { return classpath.contains(className); }
        boolean missingBean(String beanName) { return !existingBeans.contains(beanName); }
        boolean onProperty(String key, String value) { return propertyValues.getOrDefault(key, "").equals(value); }
        Map<String, String> propertyValues = new HashMap<>();
    }

    /** 模拟一个自动配置类 */
    static class DataSourceAutoConfiguration {
        String name;
        List<String> conditions = new ArrayList<>();
        Runnable action;

        DataSourceAutoConfiguration(String name) { this.name = name; }

        /** 评估所有条件,决定是否"生效" */
        boolean evaluate(ConditionEvaluator env) {
            for (String c : conditions) {
                String[] parts = c.split("=", 2);
                boolean pass = switch (parts[0]) {
                    case "onClass"     -> env.onClass(parts[1]);
                    case "missingBean" -> env.missingBean(parts[1]);
                    case "onProperty"  -> { String[] kv = parts[1].split(":"); yield env.onProperty(kv[0], kv[1]); }
                    default -> false;
                };
                System.out.printf("    条件 %-28s -> %s%n", c, pass ? "满足" : "不满足(跳过)");
                if (!pass) return false;
            }
            return true;
        }

        void apply(ConditionEvaluator env) {
            System.out.println("  [" + name + "] 条件评估:");
            if (evaluate(env)) {
                System.out.println("  ==> 自动配置生效!");
                env.existingBeans.add(name);
            } else {
                System.out.println("  ==> 不生效,跳过");
            }
        }
    }

    public static void main(String[] args) {
        System.out.println("=== 场景1: Spring Boot 默认环境(引入 starter-web) ===");
        ConditionEvaluator env = new ConditionEvaluator();
        env.classpath.addAll(List.of("org.apache.tomcat.embed.Tomcat", "com.zaxxer.hikari.HikariDataSource",
                "org.sqlite.JDBC", "org.springframework.web.servlet.DispatcherServlet"));
        env.propertyValues.put("spring.datasource.url", "jdbc:sqlite:admin.db");

        DataSourceAutoConfiguration dsAuto = new DataSourceAutoConfiguration("DataSourceAutoConfiguration");
        dsAuto.conditions.add("onClass=com.zaxxer.hikari.HikariDataSource");
        dsAuto.conditions.add("missingBean=dataSource");
        dsAuto.apply(env);
        System.out.println("  结果: 容器里现在有 " + env.existingBeans + "\n");

        System.out.println("=== 场景2: 项目自定义了数据源(SandboxDataSourceConfig) ===");
        env.existingBeans.add("dataSource"); // 自定义 @Bean 抢先注册
        System.out.println("  (模拟: 项目里已用 @Bean 声明了 dataSource)");
        dsAuto.apply(env);
        System.out.println("  结果: 自动配置退让,使用项目的自定义数据源 —— 这就是 @ConditionalOnMissingBean 的意义\n");

        System.out.println("=== 场景3: 缺少 Hikari 依赖(没引连接池) ===");
        ConditionEvaluator env2 = new ConditionEvaluator();
        env2.classpath.add("org.sqlite.JDBC"); // 只有驱动,没有连接池
        dsAuto.apply(env2);
        System.out.println("  结果: 自动配置跳过,如无自定义配置则启动失败并给出清晰报错\n");

        System.out.println("对照本项目 application.yml:");
        System.out.println("  spring.datasource.url: jdbc:sqlite:data/admin.db   <- 覆盖默认数据源");
        System.out.println("  jpa.hibernate.ddl-auto: update                      <- 覆盖建表策略");
        System.out.println("  Boot 的核心哲学: 默认开箱即用,需要时才覆盖");
    }
}

import java.util.*;

public class Main {

    // ---------- DTO 与统一响应(对照本项目 Result / LoginRequest) ----------
    record LoginRequest(String username, String password) { }

    static class Result {
        int code; String message; Object data;
        static Result ok(Object data) { return build(0, "success", data); }
        static Result fail(int code, String message) { return build(code, message, null); }
        private static Result build(int code, String message, Object data) {
            Result r = new Result(); r.code = code; r.message = message; r.data = data; return r;
        }
        public String toString() {
            return "{\"code\":" + code + ",\"message\":\"" + message
                    + "\",\"data\":" + (data == null ? "null" : "\"" + data + "\"") + "}";
        }
    }

    // ---------- 模拟业务异常与全局异常处理器 ----------
    static class BusinessException extends RuntimeException {
        BusinessException(String msg) { super(msg); }
    }

    static Result globalExceptionHandler(Exception e) {
        if (e instanceof BusinessException) return Result.fail(1001, e.getMessage());
        if (e instanceof IllegalArgumentException) return Result.fail(400, e.getMessage());
        return Result.fail(500, "服务器内部错误"); // 不泄露堆栈细节
    }

    // ---------- 模拟 Controller ----------
    static class AuthController {
        Map<String, String> users = Map.of("admin", "admin123", "user", "user123");

        Result login(LoginRequest req) {
            // 1. 参数校验(对照 @Valid)
            if (req.username() == null || req.username().isBlank())
                throw new IllegalArgumentException("用户名不能为空");
            if (req.password() == null || req.password().length() < 6)
                throw new IllegalArgumentException("密码长度不能少于 6 位");
            // 2. 业务逻辑
            if (!req.password().equals(users.get(req.username())))
                throw new BusinessException("用户名或密码错误");
            // 3. 统一响应
            return Result.ok("jwt-token-xyz");
        }
    }

    public static void main(String[] args) {
        AuthController controller = new AuthController();

        System.out.println("=== POST /api/auth/login 各种情况 ===\n");

        // 用例 1: 正常登录
        System.out.println("请求: {\"username\":\"admin\",\"password\":\"admin123\"}");
        System.out.println("响应: " + controller.login(new LoginRequest("admin", "admin123")));

        // 用例 2: 参数校验失败(空用户名)
        System.out.println("\n请求: {\"username\":\"\",\"password\":\"admin123\"}");
        try {
            controller.login(new LoginRequest("", "admin123"));
        } catch (Exception e) {
            System.out.println("响应: " + globalExceptionHandler(e));
        }

        // 用例 3: 密码太短
        System.out.println("\n请求: {\"username\":\"admin\",\"password\":\"123\"}");
        try {
            controller.login(new LoginRequest("admin", "123"));
        } catch (Exception e) {
            System.out.println("响应: " + globalExceptionHandler(e));
        }

        // 用例 4: 密码错误(业务异常)
        System.out.println("\n请求: {\"username\":\"admin\",\"password\":\"wrongpwd\"}");
        try {
            controller.login(new LoginRequest("admin", "wrongpwd"));
        } catch (Exception e) {
            System.out.println("响应: " + globalExceptionHandler(e));
        }

        System.out.println("\n=== 设计要点 ===");
        System.out.println("  1. 参数校验与业务校验分离: 前者 400,后者 1001(业务码)");
        System.out.println("  2. 所有响应同一结构,前端只判断 code");
        System.out.println("  3. 未知异常统一 500,绝不把堆栈返回给客户端");
        System.out.println("  4. 本项目对应类: AuthController / BusinessException / GlobalExceptionHandler / Result");
    }
}

import java.util.*;

public class Main {

    /** 模拟 Spring 的配置优先级(后者覆盖前者,按加载顺序) */
    static class ConfigLoader {
        Map<String, String> values = new LinkedHashMap<>();

        ConfigLoader load(String source, Map<String, String> conf) {
            System.out.println("  加载 " + source + ": " + conf);
            values.putAll(conf); // 按顺序覆盖
            return this;
        }

        String get(String key) { return values.getOrDefault(key, "<未配置>"); }
    }

    public static void main(String[] args) {
        System.out.println("=== Spring Boot 配置优先级演示(从低到高) ===\n");

        ConfigLoader config = new ConfigLoader();

        // 1. 最低: application.yml 默认值
        config.load("application.yml(默认)",
                Map.of("server.port", "8080",
                       "spring.datasource.url", "jdbc:sqlite:data/admin.db",
                       "logging.level.root", "INFO"));

        // 2. application-prod.yml(profile 差异)
        config.load("application-prod.yml",
                Map.of("logging.level.root", "WARN",
                       "spring.datasource.url", "jdbc:mysql://prod-db:3306/app"));

        // 3. 环境变量(生产注入密钥,不写进代码库)
        config.load("环境变量(SPRING_DATASOURCE_PASSWORD)",
                Map.of("spring.datasource.password", "******(来自密钥管理)"));

        // 4. 最高: 命令行参数
        config.load("命令行参数",
                Map.of("server.port", "9090"));

        System.out.println("\n=== 最终生效配置 ===");
        for (String key : new String[]{"server.port",
                "spring.datasource.url", "spring.datasource.password", "logging.level.root"}) {
            System.out.printf("  %-28s = %s%n", key, config.get(key));
        }

        System.out.println("\n=== 覆盖规则总结 ===");
        System.out.println("  命令行 > 环境变量 > application-{profile}.yml > application.yml");
        System.out.println("  实践要点:");
        System.out.println("    - 密码/密钥只放环境变量或配置中心,永不入库");
        System.out.println("    - server.port 被命令行覆盖成 9090 -> 一个 jar 多处部署");

        System.out.println("\n=== 本项目部署命令回顾 ===");
        System.out.println("  mvn clean package");
        System.out.println("  java -jar target/spring-boot-learning-1.0.0.jar");
        System.out.println("  java -jar app.jar --spring.profiles.active=prod --server.port=9090");
        System.out.println("  后台: nohup java -jar app.jar > app.log 2>&1 &");
    }
}

import java.util.*;

public class Main {

    // ---------- 单体: 一个进程内的模块调用 ----------
    static class MonolithApp {
        Map<String, Object> createOrder(String user, String item) {
            // 全部在一个 JVM 内,方法调用 = 内存跳转(纳秒级)
            String userId = userModule_validate(user);
            String stock = stockModule_lock(item);
            String pay = payModule_charge(userId);
            return Map.of("orderId", "NO-" + System.nanoTime() % 10000,
                    "user", userId, "stock", stock, "pay", pay);
        }
        String userModule_validate(String u) { return "用户[" + u + "]有效"; }
        String stockModule_lock(String i) { return "库存[" + i + "]已锁定"; }
        String payModule_charge(String u) { return "支付成功"; }
    }

    // ---------- 微服务: 同样的业务,跨网络调用 ----------
    static class MicroserviceApp {
        // 模拟一次远程调用: 序列化 -> 网络 -> 反序列化 -> 可能的超时/重试
        static String remoteCall(String service, String action) {
            try { Thread.sleep(15); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            return service + ":" + action + " 成功";
        }

        Map<String, Object> createOrder(String user, String item) {
            System.out.println("    [网关] 接收请求,路由到订单服务");
            String userId = remoteCall("用户服务", "校验" + user);
            String stock = remoteCall("库存服务", "锁定" + item);
            String pay = remoteCall("支付服务", "扣款");
            return Map.of("orderId", "NO-" + System.nanoTime() % 10000,
                    "user", userId, "stock", stock, "pay", pay);
        }
    }

    public static void main(String[] args) {
        System.out.println("=== 单体架构: 一次下单 ===");
        long t1 = System.currentTimeMillis();
        var order1 = new MonolithApp().createOrder("张三", "iPhone");
        long single = System.currentTimeMillis() - t1;
        System.out.println("  结果: " + order1);
        System.out.println("  耗时: " + single + "ms (方法调用,几乎为 0)\n");

        System.out.println("=== 微服务架构: 同样的下单 ===");
        long t2 = System.currentTimeMillis();
        var order2 = new MicroserviceApp().createOrder("张三", "iPhone");
        long micro = System.currentTimeMillis() - t2;
        System.out.println("  结果: " + order2);
        System.out.println("  耗时: " + micro + "ms (3 次远程调用,每次 15ms 模拟网络)\n");

        System.out.println("=== 代价与收益 ===");
        System.out.println("  代价:");
        System.out.println("    - 延迟: " + single + "ms -> " + micro + "ms (网络往返)");
        System.out.println("    - 复杂度: 需要注册中心/网关/熔断/链路追踪");
        System.out.println("    - 一致性: 跨服务无法用单个数据库事务");
        System.out.println("  收益:");
        System.out.println("    - 独立发布(订单服务上线不影响用户服务)");
        System.out.println("    - 独立伸缩(支付服务扛不住时单独扩容)");
        System.out.println("    - 故障隔离(库存服务挂了,商品浏览仍可用)");
        System.out.println("\n务实建议: 先做好单体模块化,真有痛点再拆;拆晚了没事,拆早了要命");
    }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {

    // ---------- 1. 迷你注册中心(对照 Nacos / Eureka) ----------
    static class ServiceRegistry {
        // 服务名 -> 实例地址列表
        private final Map<String, List<String>> services = new ConcurrentHashMap<>();
        private final Map<String, Long> heartbeats = new ConcurrentHashMap<>();

        void register(String serviceName, String address) {
            services.computeIfAbsent(serviceName, k -> new CopyOnWriteArrayList<>()).add(address);
            heartbeats.put(address, System.currentTimeMillis());
            System.out.println("  [注册中心] " + serviceName + " 注册实例: " + address
                    + " (共 " + services.get(serviceName).size() + " 个实例)");
        }

        /** 心跳续约: 超时未续约的实例会被摘除 */
        void heartbeat(String address) { heartbeats.put(address, System.currentTimeMillis()); }

        List<String> discover(String serviceName) {
            List<String> list = services.getOrDefault(serviceName, List.of());
            System.out.println("  [注册中心] " + serviceName + " 被查询,返回 " + list.size() + " 个可用实例");
            return list;
        }

        void healthCheck(long timeoutMs) {
            long now = System.currentTimeMillis();
            heartbeats.forEach((addr, last) -> {
                if (now - last > timeoutMs) {
                    services.values().forEach(l -> l.remove(addr));
                    System.out.println("  [注册中心] 实例心跳超时,已摘除: " + addr);
                }
            });
        }
    }

    // ---------- 2. 客户端负载均衡(轮询,对照 Spring Cloud LoadBalancer) ----------
    static class RoundRobinLoadBalancer {
        private final AtomicInteger counter = new AtomicInteger();
        private final ServiceRegistry registry;

        RoundRobinLoadBalancer(ServiceRegistry registry) { this.registry = registry; }

        String choose(String serviceName) {
            List<String> instances = registry.discover(serviceName);
            if (instances.isEmpty()) throw new IllegalStateException("没有可用实例: " + serviceName);
            String chosen = instances.get(Math.abs(counter.getAndIncrement()) % instances.size());
            System.out.println("  [负载均衡] 轮询选中: " + chosen);
            return chosen;
        }
    }

    // ---------- 3. 迷你网关(对照 Spring Cloud Gateway) ----------
    static class Gateway {
        private final Map<String, String> routeRules = new LinkedHashMap<>(); // 路径前缀 -> 服务名
        private final RoundRobinLoadBalancer lb;
        private final Map<String, String> tokens = Map.of("valid-token-123", "admin");

        Gateway(RoundRobinLoadBalancer lb) { this.lb = lb; }

        void route(String pathPrefix, String serviceName) {
            routeRules.put(pathPrefix, serviceName);
            System.out.println("  [网关] 路由规则: " + pathPrefix + "** -> " + serviceName);
        }

        String forward(String path, String token) {
            System.out.println("\n  [网关] 收到请求: " + path);
            // 步骤1: 统一鉴权(下游服务不再各自校验)
            if (token == null || !tokens.containsKey(token)) {
                System.out.println("  [网关] 鉴权失败 -> 返回 401");
                return "401 Unauthorized";
            }
            System.out.println("  [网关] 鉴权通过,用户: " + tokens.get(token));
            // 步骤2: 匹配路由
            for (Map.Entry<String, String> e : routeRules.entrySet()) {
                if (path.startsWith(e.getKey())) {
                    System.out.println("  [网关] 匹配路由 " + e.getKey() + "** -> " + e.getValue());
                    // 步骤3: 负载均衡选实例 -> 转发
                    String instance = lb.choose(e.getValue());
                    return "200 OK (来自 " + instance + " 的响应)";
                }
            }
            System.out.println("  [网关] 无匹配路由 -> 404");
            return "404 Not Found";
        }
    }

    public static void main(String[] args) throws Exception {
        ServiceRegistry registry = new ServiceRegistry();
        RoundRobinLoadBalancer lb = new RoundRobinLoadBalancer(registry);
        Gateway gateway = new Gateway(lb);

        System.out.println("=== 1. 服务启动并注册 ===");
        registry.register("user-service", "10.0.0.1:8081");
        registry.register("user-service", "10.0.0.2:8081");
        registry.register("order-service", "10.0.0.3:8082");

        System.out.println("\n=== 2. 网关配置路由 ===");
        gateway.route("/api/user", "user-service");
        gateway.route("/api/order", "order-service");

        System.out.println("\n=== 3. 客户端请求(观察负载均衡轮询) ===");
        System.out.println("  -> " + gateway.forward("/api/user/profile", "valid-token-123"));
        System.out.println("  -> " + gateway.forward("/api/user/orders", "valid-token-123"));
        System.out.println("  -> " + gateway.forward("/api/order/create", "valid-token-123"));

        System.out.println("\n=== 4. 未携带令牌(网关统一拦截) ===");
        System.out.println("  -> " + gateway.forward("/api/user/profile", null));

        System.out.println("\n=== 5. 实例故障 -> 摘除 -> 流量自动转移 ===");
        System.out.println("  (模拟 10.0.0.1 心跳超时)");
        registry.heartbeat("10.0.0.2:8081"); // 只有 0.2 续约
        registry.healthCheck(50);
        Thread.sleep(60);
        registry.heartbeat("10.0.0.2:8081");
        System.out.println("  -> " + gateway.forward("/api/user/profile", "valid-token-123"));

        System.out.println("\n=== 组件对照表 ===");
        System.out.println("  迷你实现              生产方案");
        System.out.println("  ServiceRegistry       Nacos / Eureka");
        System.out.println("  RoundRobinLoadBalancer Spring Cloud LoadBalancer");
        System.out.println("  Gateway               Spring Cloud Gateway");
        System.out.println("  下一步可自行扩展: 熔断(Resilience4j)、配置中心、链路追踪");
    }
}

lessons.content:
"转账 100 元"其实是两步:A 账户 -100、B 账户 +100。如果第一步成功、第二步失败,钱就凭空消失了。事务(Transaction)就是把多条语句打包成"要么全做、要么全不做"的原子单元。

## 事务控制
```sql
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;   -- 两步都成功,一次性生效
```
中途出问题执行 ROLLBACK,数据库回到 BEGIN 之前的状态,仿佛什么都没发生。

## ACID 四大特性
- Atomicity 原子性:全成或全败,不允许"做了一半"
- Consistency 一致性:事务前后,数据满足所有约束(总额不变)
- Isolation 隔离性:并发事务互不干扰(细节见下一课)
- Durability 持久性:COMMIT 之后即使断电,数据也不丢(靠日志实现)

## 自动提交
多数数据库和驱动默认"自动提交":每条独立语句自带 BEGIN+COMMIT。要手动控制,先关闭自动提交或显式 BEGIN。沙箱里每条语句就是独立事务,所以 INSERT 之后立刻可见,也正因如此,沙箱的"重置数据"能一键还原。

## 与 Java 的衔接(重点)
本项目 Java 阶段的 JDBC 章节会亲手写:
```java
conn.setAutoCommit(false);
try {
    stmt.executeUpdate("UPDATE ...");
    stmt.executeUpdate("UPDATE ...");
    conn.commit();
} catch (Exception e) {
    conn.rollback();
}
```
Spring 的 @Transactional 注解就是对这套逻辑的封装——回滚规则、传播行为,底层全是这里学的 BEGIN/COMMIT。SQL 学得越扎实,JDBC 那章越轻松。

## 易错点
- 忘记 COMMIT 就断开连接,事务被自动回滚,改动"神秘消失"
- 事务里塞入远程调用(HTTP 请求),长事务拖垮数据库连接池
- 大事务(一次更新百万行)持锁太久,阻塞其他请求——应分批提交

## 动手练习
1. 用一句话解释 ACID 各自防住什么事故
2. 为什么"转账"必须用事务,而"查询余额"不需要?
3. 预习:REPEATABLE READ 和 READ COMMITTED 有什么区别?下一课揭晓
